  str_aircraft_tactic_mission_name_10_10_3 = "ซิมูเลชั่นการประลอง 10 (ยาก)",
  str_aircraft_tactic_info11101 = "แม่น้ำทองคำ: มีต้นกำเนิดมาจากสุดขอบโลก เป็นแม่น้ำสายที่ยาวที่สุดในดินแดนแอสตรา โดยน้ำของแม่น้ำสายนี้มาจากหิมะที่ปกคลุมเทือกเขาด้านบนละลายไหลลงสู่ด้านล่าง และไหลผ่านไปทั่วทั้งทวีป",
  str_aircraft_tactic_info11102 = "ชีวิตความเป็นอยู่ตามแนวแม่น้ำทองคำ: หมู่บ้านในแถบนี้ตั้งอยู่ตามลุ่มแม่น้ำทองคำ โดยกินดีมีสุขได้เพราะแม่น้ำทองคำที่ไหลผ่านและชายฝั่งแม่น้ำทองคำที่อุดมสมบูรณ์ ริมฝั่งแม่น้ำสายหลักมีหมู่บ้านต่าง ๆ ที่มีความเจริญมาก ที่อาศัยการสื่อสารที่ก้าวหน้าและการค้าที่แข็งแกร่งมาพัฒนาแหล่งชุมชน",
  str_aircraft_tactic_info11103 = "ข้าวปลาอาหารของหมู่บ้าน: ชาวบ้านริมแม่น้ำทองคำมักกินถั่วและผลิตภัณฑ์จากถั่ว รวมถึงปลาหมักและเนื้อสัตว์ต่าง ๆ อาหารจำพวกนี้หาได้ง่ายและมีอยู่มากที่สุด",
  str_aircraft_tactic_info11104 = "การค้า: พ่อค้าจำนวนมากในพื้นที่แม่น้ำทองคำหากินตามเส้นทางที่กำหนดขึ้นโดยเฉพาะ เร่ขายสินค้าไปตามเมืองใหญ่ที่มีความมั่งคั่งตามริมฝั่งแม่น้ำ",
  str_aircraft_tactic_info11201 = "แม่น้ำทองคำ: แม่น้ำทองคำทอดตัวอย่างไร้ที่สิ้นสุดไปทั่วผืนแผ่นดิน ไหลจากทางตะวันตกเฉียงเหนือไปยังตะวันออกเฉียงใต้ และในที่สุดก็ไหลออกสู่ทะเล",
  str_aircraft_tactic_info11202 = "ชีวิตความเป็นอยู่ตามแนวแม่น้ำทองคำ: หมู่บ้านที่อยู่ใกล้กิ่งก้านสาขาของแม่น้ำทองคำยังคงยึดถือวิถีชีวิตแบบดั้งเดิม ชาวบ้านยังคงหาปลาเลี้ยงชีพและทดน้ำจากแม่น้ำเข้าสู่ไร่นาของตนเอง",
  str_aircraft_tactic_info11203 = "อาหารของหมู่บ้าน: ชาวบ้านยังปลูกข้าวสาลี แต่แทบไม่ได้ใช้เพื่อการบริโภค ข้าวสาลีจะถูกนำไปหมักเป็นเบียร์ ซึ่งเป็นสิ่งที่ขาดไม่ได้สำหรับคนท้องถิ่นจำนวนมาก",
  str_aircraft_tactic_info11204 = "การค้า: เมื่อมีโอกาสพิเศษ พ่อค้าบางส่วนเต็มใจที่จะเปิดเส้นทางการค้าใหม่ทั่วดินแดน แต่เนื่องด้วยสถานการณ์ที่ไม่คุ้นเคยและมีความเสี่ยง พวกเขาจึงมักถูกคุ้มกันโดยทหารรักษาการณ์",
  str_aircraft_tactic_info11301 = "ลูมินาติกส์: ไม่ใช่ออโรเรียนทุกคนที่เกิดมาพร้อมความสามารถในการใช้ลูมินาติกส์ มันเป็นเหมือนความสามารถที่รอการปลุกขึ้นมามากกว่า",
  str_aircraft_tactic_info11302 = "บิสกิตเสบียงลูโมโพลิส: เสบียงมาตรฐานสำหรับทหารลูโมโพลิส ทำจากขนมปังขาวที่อุดมด้วยเกลือและน้ำตาลที่เหมาะสมและผสมกับลูมินาติกส์",
  str_aircraft_tactic_info11303 = "เกราะเหล็ก: ชุดเกราะที่อัศวินสวมใส่และจัดหามาให้โดยคริสตจักร อัศวินส่วนใหญ่มีเกราะหนักแต่มีความสามารถในป้องกัน และอัศวินบางกลุ่มให้ความสำคัญกับความคล่องตัวมากกว่าการป้องกันและสวมใส่เกราะโซ่ถัก",
  str_aircraft_tactic_info11304 = "โล่ใหญ่: อุปกรณ์ของอัศวินลูโมอันเป็นเอกลักษณ์และขาดไม่ได้ แสดงถึงความเกี่ยวข้องกับกลุ่มอัศวินแห่งลูโมโพลิส รูปร่างและขนาดของโล่อาจแตกต่างกันเล็กน้อยขึ้นอยู่กับทหารที่ถือโล่ แต่เสื้อคลุมแขนที่สวมใส่อยู่ยังคงไม่เปลี่ยนแปลง",
  str_aircraft_tactic_info11401 = "ลูมินาติกส์: มีอยู่หลายสาเหตุที่สามารถกระตุ้นพลังนี้ได้ คำแนะนำของบางคนบอกว่าเป็นช่วงเวลาที่สำคัญที่สุดในประวัติศาสตร์ของคน ๆ นั้น... ชาวออโรเรียนหลายคนใช้ชีวิตทั้งชีวิตโดยไม่เคยได้ใช้ลูมินาติกส์ แต่แสงแดดก็สาดส่องมาที่พวกเขาเหมือนกันหมด",
  str_aircraft_tactic_info11402 = "บิสกิตเสบียงลูโมโพลิส: บิสกิตไม่เพียงแต่เก็บได้นาน มันยังรสชาติอร่อยขึ้น น้ำหนักเบา พกพาง่าย สมดุลด้วยความหวานและความเค็ม เสบียงทหารนี้อาจทำมาเพื่อดับความหิวโหยของทหาร แต่รสชาติของมันยังดีกว่าอาหารทั่วไปที่คนธรรมดากินกันอีกด้วย",
  str_aircraft_tactic_info11403 = "เกราะเหล็ก: อัศวินบางคนเลือกที่จะใส่เกราะสั่งทำ ในสถานการณ์ต่อสู้บางครั้ง มีอัศวินที่เลือกจะสวมใส่ชุดเกราะหลาย ๆ แบบเข้าด้วยกัน",
  str_aircraft_tactic_info11404 = "โล่ยักษ์: คริสตจักรจะมอบโล่ให้กับอัศวินในวันที่พวกเขาถูกแต่งตั้งประจำการ ซึ่งเป็นสัญลักษณ์ของความเชื่อของลูโมโพลิสว่าการปกป้องมีความสำคัญมากกว่าการพิชิต โล่ถูกมองว่ามีพลังมากกว่าดาบและมีความหมายเหมือนกันกับความกล้าหาญและหน้าที่",
  str_aircraft_tactic_info11501 = "สหภาพผู้ส่งสาร: องค์กรบริการไปรษณีย์ที่มีมานานหลายศตวรรษ แม้จะมีสมาชิกจำนวนน้อย แต่ก็ได้รับการยกย่องอย่างกว้างขวางทั่วแอสตราสำหรับการจัดส่งที่รวดเร็วและมีประสิทธิภาพ",
  str_aircraft_tactic_info11502 = "ไปรษณีย์: สิ่งปลูกสร้างเฉพาะของสหภาพผู้ส่งสารที่ทำหน้าที่เป็นสถานที่พักผ่อนสำหรับผู้ส่งสาร และจัดหาอาหารและเสบียงอื่น ๆ ที่จำเป็นในการเดินทาง ผู้ที่ต้องการส่งจดหมายยังสามารถฝากจดหมายของพวกเขาได้ที่นี่เช่นกัน",
  str_aircraft_tactic_info11503 = "กำหนดการเดินทาง: สมุดบันทึกเหล่านี้บันทึกการเดินทางของผู้ส่งสารขณะออกไปนำส่งพัสดุ",
  str_aircraft_tactic_info11504 = "ดอกแดนดิไลอัน: ดอกไม้พิเศษที่เป็นสัญลักษณ์ของอีราเวล เป็นที่รักของชาวเคเลสไทต์ทั้งหมดเนื่องจากมีสีขาวและปุกปุยตลอดจนเป็นตัวแทนของเสรีภาพ",
  str_aircraft_tactic_info11601 = "สหภาพผู้ส่งสาร: สหภาพผู้ส่งสารมักถูกจ้างวานให้จัดส่งของระยะไกลข้ามพรมแดน บางครั้งต้องผ่านเส้นทางอันตรายที่ถูกปิดห้ามบุคคลธรรมดาเข้า",
  str_aircraft_tactic_info11602 = "ไปรษณีย์: นอกจากนี้ยังมีกล่องจดหมายที่ทางเข้าของไปรษณีย์เหล่านี้ ผู้ที่ต้องการให้ส่งจดหมายสามารถส่งมาได้ที่นี่ และผู้ส่งสารคนต่อไปที่มาถึงที่ไปรษณีย์จะรับไว้สำหรับการจัดส่ง",
  str_aircraft_tactic_info11603 = "กำหนดการเดินทาง: ผู้ส่งสารบันทึกจดหมายที่พวกเขาส่งหรือกำลังส่งอยู่ ไปรษณีย์ที่พวกเขาหยุดพักผ่อนและอื่น ๆ เรียกได้ว่าเป็นของใช้ส่วนตัวที่สำคัญที่สุดของผู้ส่งสาร",
  str_aircraft_tactic_info11604 = "ดอกแดนดิไลออน: แม้จะมีอยู่เต็มไปหมดในอีราเวล แต่ชาวเคเลสไทต์ก็ชอบสร้างวัตถุและของประดับตกแต่งตามภาพในช่วงวันหยุด",
  str_aircraft_tactic_info11701 = "แอชูไรต์: เกาะลอยน้ำขนาดมหึมาที่ลอยอยู่เหนือที่ราบแอสตรา เมื่อหลายปีก่อน ชาวออโรเรียนทางเหนืออันห่างไกลต้องต่อสู้กับทั้งสภาพแวดล้อมที่ไม่เอื้ออำนวยในบ้านเกิดของพวกเขาและภัยคุกคามอิคลิพไซท์ ออกจากบ้านของพวกเขาไปถึงแอสตรา และในที่สุดก็พบวิธีที่จะปีนขึ้นไปบนแอชูไรต์ได้",
  str_aircraft_tactic_info11702 = "ท่าจอดยาน: ท่าจอดยานในลูโมโพลิสชั้นล่าง เป็นท่าจอดเดียวสำหรับเข้าเมือง เรือเหาะทุกลำที่เดินทางเข้าและออกจากลูโมโพลิสจะต้องผ่านสถานที่นี้และต้องได้รับการตรวจสอบอย่างเข้มงวดโดยไม่คำนึงว่าจะเดินทางไปไหน ในหลายกรณี ต้องส่งคำขอล่วงหน้าเพื่อที่จะผ่านด่านนี้",
  str_aircraft_tactic_info11703 = "อัมบราตัน และแอชูไรต์: ในฐานะที่เป็นเมืองที่ใกล้ที่สุดสำหรับแอชูไรต์ อัมบราตันคือจุดเชื่อมต่อระหว่างลูโมโพลิสและโลกภายนอก",
  str_aircraft_tactic_info11704 = "เรือเหาะ: วิธีหลักในการเดินทางไปและกลับจากลูโมโพลิส ขึ้นอยู่กับสถานที่ผลิต เรือเหาะที่แตกต่างกันไม่เพียงแต่จะมีรูปลักษณ์ที่แตกต่างกันเท่านั้น แต่ยังมีระบบขับเคลื่อนที่แตกต่างกันอีกด้วย ตัวอย่างของความแตกต่างเหล่านี้คือเรือเหาะที่ผลิตในอิลลูมินา ซึ่งเป็นการออกแบบทางอุตสาหกรรมและขับเคลื่อนด้วยความร้อน ในทางกลับกัน เรือเหาะลูโมโพลิส เน้นไปที่ความงามภายนอกและความสง่างามมากกว่า และขับเคลื่อนโดยลูมินา",
  str_aircraft_tactic_info11801 = "แอชูไรต์: ชาวออโรเรียนก่อตั้งขึ้นมาโดยมีสังคมชั้นสูงเป็นแกนหลัก ระเบียบทางสังคมที่อิงตามระบบจักรวรรดิโบราณ ดังนั้นเกาะแอชูไรต์จึงกลายเป็นเมืองลูโมโพลิส เมืองใหญ่ลอยอยู่บนท้องฟ้า",
  str_aircraft_tactic_info11802 = "ท่าจอดยาน: ท่าจอดยานถูกแบ่งเป็น 4 ส่วน แต่ละส่วนแบ่งเป็นประเภท: ท่องเที่ยว ขนส่ง การทหาร และพิเศษ",
  str_aircraft_tactic_info11803 = "อัมบราตัน และแอชูไรต์: ท่าเรือเรือเหาะสำหรับเข้าและออกจากลูโมโพลิสได้รับการจัดตั้งขึ้นที่นี่ภายใต้เขตอำนาจศาลของลูโมโพลิสแต่เพียงผู้เดียว ในกรณีส่วนใหญ่ เราต้องผ่านอัมบราตันเพื่อเข้าสู่แอชูไรต์",
  str_aircraft_tactic_info11804 = "เรือเหาะ: ท่าเรืออัมบราตัน และลูโมโพลิสให้บริการเรือเหาะเพื่อใช้เป็นพาหนะในการขนส่งสาธารณะสำหรับพลเมืองของตน พลเมืองที่มีชื่อเสียงและร่ำรวยบางคนมีเรือเหาะส่วนตัวอีกด้วย",
  str_aircraft_tactic_info11901 = "ป้ายของผู้ส่งสาร: ป้ายสลักด้วยปากกาขนนกบนพื้นผิว เหรียญอันมีค่าที่พิสูจน์ตัวตนของผู้สวมใส่ในฐานะสมาชิกของสหภาพผู้ส่งสาร มักจะถูกมองเห็นห้อยลงมาจากสมุดแผนการเดินทางของผู้ส่งสาร",
  str_aircraft_tactic_info11902 = "ลูโมโพลิสชั้นล่าง: ศูนย์กลางการผลิตทางการเกษตรและอุตสาหกรรมของเมือง พื้นที่ที่อยู่อาศัยค่อนข้างเล็ก แต่ความหนาแน่นของประชากรสูงที่สุดในลูโมโพลิสทั้งหมด",
  str_aircraft_tactic_info11903 = "ภายในท่าจอดยาน: ศูนย์กลางกิจกรรมเชิงพาณิชย์ที่คึกคักที่สุดในลูโมโพลิสทั้งหมด ที่นี่คุณจะพบผู้คนหลากหลายรูปแบบ ทั้งพ่อค้าและคนชั้นสูงที่รอเรือเหาะ รวมถึงนักท่องเที่ยวกระเป๋าหนักจำนวนมาก",
  str_aircraft_tactic_info11904 = "สินค้าโภคภัณฑ์ของลูโมโพลิส: ค้าขายในสินค้าฟุ่มเฟือยเป็นหลัก โดยทั่วไปแล้วสิ่งของต่าง ๆ ใน ลูโมโพลิส ประกอบด้วยเครื่องประดับทองและเงิน อัญมณีล้ำค่า และขนสัตว์อันงดงาม",
  str_aircraft_tactic_info12001 = "ป้ายของผู้ส่งสาร: ไปรษณีย์แต่ละแห่งมีป้ายสำรองหลายอัน ในกรณีที่ผู้ส่งสารทำหาย",
  str_aircraft_tactic_info12002 = "ลูโมโพลิสตอนล่าง: ที่นี่คือบ้านของชนชั้นสูงที่ลดระดับลงมา เช่นเดียวกับคนรับใช้ของขุนนางชั้นกลางและชั้นสูง เป็นสถานที่รวมอย่างแท้จริงของเมืองและในชนบท โดยเฉพาะอย่างยิ่งเมื่อเปรียบเทียบกับสวนลูโมโพลิสหรือลานลานลูโมโพลิส",
  str_aircraft_tactic_info12003 = "ท่าจอดยาน: บรรดาพ่อค้าแม่ค้าที่มองการณ์ไกลได้ค้นพบโอกาสในศูนย์กลางแห่งนี้แล้ว โดยขายทุกอย่างตั้งแต่สินค้าหรูหราไปจนถึงอาหารขึ้นชื่อในท้องถิ่น",
  str_aircraft_tactic_info12004 = "สินค้าของลูโมโพลิส: นอกจากนี้ยังสามารถพบสินค้านำเข้าที่หายากและแปลกใหม่ได้ที่นี่ เช่น เครื่องเทศและส่วนผสมจากดินแดนที่ห่างไกล",
  str_aircraft_tactic_info12101 = "ความรับผิดชอบของอัศวินลูโม: สังกัดส่วนทางการทหารของลูโมโพลิส หน้าที่หลักของอัศวินลูโมคือคือการขับไล่การโจมตีอิคลิพไซต์ระดับสูงและค้นหาซากอารยธรรมโบราณ",
  str_aircraft_tactic_info12102 = "สลัมลูโมโพลิสชั้นล่าง: สลัมลูโมโพลิสชั้นล่างเป็นสิ่งที่ไม่น่าดูมากที่สุดเมื่อเทียบกับความยิ่งใหญ่ของเมือง ที่นั่นมีอาคารหินที่ทรุดโทรมส่วนใหญ่ถูกทิ้งร้าง และถนนเป็นสีเทาและเต็มไปด้วยขยะ เนื่องจากไม่ได้รับการบำรุงรักษาตามปกติ ผู้อยู่อาศัยในสลัมสวมใส่ตัวเองด้วยเสื้อผ้าที่เป็นขุยตามที่พวกเขาหาได้",
  str_aircraft_tactic_info12103 = "เจ้าหน้าที่สันติบาล: ทหารคุ้มกันที่มีหน้าที่รักษากฎหมายและความสงบในลูโมโพลิส ตลอดจนปกป้องตระกูลชวาตส์",
  str_aircraft_tactic_info12104 = "ชีวิตพลเรือนในลูโมโพลิส: พลเรือนส่วนใหญ่ของเมืองกระจุกตัวอยู่ที่ลูโมโพลิสชั้นล่าง ซึ่งพวกเขาไม่เพียงแค่ไปทำงานเท่านั้น แต่ยังใช้เวลาอยู่ในบาร์ คาเฟ่ ร้านค้า และโรงละครอีกด้วย",
  str_aircraft_tactic_info12201 = "ความรับผิดชอบของอัศวินลูโม: ภายใต้สถานการณ์ปกติ หน้าที่ประจำวันของพวกเขาคือการรักษากฎหมายและความสงบภายในเมือง",
  str_aircraft_tactic_info12202 = "สลัมลูโมโพลิสชั้นล่าง: แม้ว่ากฎหมายและระเบียบแทบจะไม่มีอยู่ในสถานที่นี้ ดูเหมือนว่าแสงแดดจะหันหน้าไปจากส่วนนี้ของเมือง ปล่อยให้มันตัวสั่นและเสื่อมสลายไปในความมืด",
  str_aircraft_tactic_info12203 = "เจ้าหน้าที่สันติบาล: ทหารคุ้มกันถูกแบ่งออกเป็นกลุ่มเล็ก ๆ หลายกลุ่ม ซึ่งแต่ละกลุ่มมีหน้าที่ปกป้องพื้นที่เมืองที่แตกต่างกัน ตัวอย่างเช่น ผู้ที่ได้รับมอบหมายให้ปกป้องสวนลูโมโพลิสเรียกว่าทหารคุ้มกันสวนลูโม ในทำนองเดียวกัน ผู้ที่ได้รับมอบหมายให้รักษาความสงบเรียบร้อยโดยทั่วไปเรียกว่าเจ้าหน้าที่สันติบาล",
  str_aircraft_tactic_info12204 = "ชีวิตพลเรือนในลูโมโพลิส: พลเมืองส่วนใหญ่แทบไม่มีความหวังเลยว่าจะไปถึงจุดสูงสุดแบบเหล่าขุนนางชั้นสูง พวกเขาชอบที่จะยุ่งกับงานอดิเรกที่เรียบง่ายและราคาไม่แพง",
  str_aircraft_tactic_info12301 = "วิกฤตดาร์กโอเวอร์: วิกฤตดาร์กโอเวอร์เริ่มขึ้นเมื่อ 17 ปีที่แล้วเมื่อองค์กรที่รู้จักกันในชื่ออิคลิพส์พยายามยึดครองโคลอสซัส เครื่องบินยักษ์ใหญ่ขนาดมหึมาจากอารยธรรมที่สูญหายไป ด้วยกองอิคลิพไซท์ พวกมันล้อมโจมตีอีราเวล ถิ่นกำเนิดของเผ่าเคเลสไทต์ เหลือผู้รอดชีวิตไม่กี่คนจากการฆ่าล้างเผ่าพันธุ์ ในที่สุด 7 ปีต่อมา กองทัพอิคลิพไซท์ก็ถูกจัดการโดยกองกำลังผสมที่รวมกันของแอสตรา และวิกฤตดาร์กโอเวอร์ก็สิ้นสุดลง",
  str_aircraft_tactic_info12302 = "รูปปั้นราชินีเบธเลเฮม: ชาวนอร์ธแลนด์ชื่นชอบราชินีของพวกเขาอย่างมาก เนื่องด้วยวิถีชีวิตทางตอนเหนือที่ค่อนข้างช้า ชาวออโรเรียนผู้คล่องแคล่วแห่งนอร์ธแลนด์จึงใช้เวลาว่างส่วนใหญ่ไปกับงานแกะสลักไม้ต่าง ๆ งานแกะสลักที่ทำขึ้นตามแบบพระราชินีเบธเลเฮมเป็นสิ่งที่พบได้บ่อยที่สุดในสถานที่เหล่านี้",
  str_aircraft_tactic_info12303 = "ลูกอมนกหวีดลูโม: ลูกอมเม็ดเล็กอันเป็นที่โปรดปรานของเด็ก ๆ โดยเฉพาะ ซึ่งจะส่งเสียงหวีดหวิวเมื่อถูกเป่า สำหรับชาวออโรเรียนหลาย ๆ คนแล้ว มันเป็นเรื่องที่ล้ำค่ามาก แม้แต่ผู้ใหญ่บางครั้งก็ซื้อเพื่อระลึกถึงความทรงจำในวัยเด็กของพวกเขา",
  str_aircraft_tactic_info12304 = "ขนมกรุบกรอบเคี้ยวเพลิน: ขนมขบเคี้ยวพิเศษที่มีชื่อเสียงจากพื้นที่ทะเลทรายของแอสตรา รูปลักษณ์ของมันอาจทำให้คนภายนอกดูไม่ชอบใจเล็กน้อย แต่ในนั้นมีเสน่ห์ดึงดูดอยู่ ทำมาจากกิ้งก่าตัวเล็ก ๆ ที่ทอดแล้วตากให้แห้งจนกรอบ พวกมันยังคงรักษารูปร่างและท่าทางดั้งเดิมไว้ตั้งแต่ตอนที่พวกมันยังมีชีวิตอยู่ ค่อนข้างน่าสยดสยอง แต่บางทีนี่อาจเป็นส่วนหนึ่งของอารมณ์ขันของชาวทะเลทราย",
  str_aircraft_tactic_pic_name1 = "รุ่งอรุณแห่งการเดินทาง",
  str_aircraft_tactic_pic_name2 = "ลำนำแดนหิมะ",
  str_aircraft_tactic_pic_name3 = "จดหมายระหว่างโรซ่าและ M&M",
  str_aircraft_tactic_pic_name4 = "คุณนายเร้ด เมอร์คิวรี",
  str_aircraft_tactic_locked_condition = "ปลดล็อกเบาะแส 4 ชิ้นเพื่อรับ!",
  str_aircraft_tactic_info21101 = "ผู้อาวุโส: เหล่าขุนนางและผู้อาวุโสได้รับการแต่งตั้งให้ปกครองหมู่บ้านและเมืองขนาดเล็ก และในบางกรณีก็ให้ชาวบ้านปกครองถิ่นฐานร่วมกัน อย่างไรก็ตาม หมู่บ้านและเมืองทั้งหมดต้องปฏิบัติตามคำสั่งของครอบครัวแห่งราชวงศ์นอร์ธแลนด์หากมีเหตุการณ์สำคัญ",
  str_aircraft_tactic_info21102 = "ปลากระป๋องเฮอร์ริ่ง: ไอเทมอาหารพิเศษจากนอร์ธแลนด์ที่สามารถเก็บได้นาน คนท้องถิ่นนิยมเป็นอย่างมากแต่บุคคลภายนอกมักรู้สึกว่ากลิ่นและรสชาตินั้นเข้มข้นเกินไป",
  str_aircraft_tactic_info21103 = "ขนมกัมมี่: นอร์ธแลนด์เป็นดินแดนของเบอร์รี่ป่าหลากหลายสายพันธุ์ และขนมกัมมี่นุ่มนิ่มที่พวกเขาทำก็เป็นของโปรดของเด็ก ๆ ทั่วอาณาจักร",
  str_aircraft_tactic_info21104 = "เนื้อฉลามหมัก: ด้วยเหตุอันใดมิอาจทราบได้ ฉลามกลายพันธุ์และปรากฏตัวในน่านน้ำเย็นยะเยือกที่นอร์ธแลนด์ เนื้อฉลามสามารถกินได้อย่างปลอดภัยหลังผ่านขั้นตอนการหมักพิเศษแล้ว",
  str_aircraft_tactic_info22101 = "กระท่อมมุงหลังคา: สิ่งปลูกสร้างที่ใช้เก็บข้าวและไม้ ถึงแม้จะมีรูปร่างธรรมดาแต่ก็สามารถกันลมได้ค่อนข้างดี",
  str_aircraft_tactic_info22102 = "การอพยพประชากรของนอร์ธแลนด์: เยาวชนมากมายของนอร์ธแลนด์ออกจากดินแดนที่ล้าหลังและหนาวเย็นนี้ไปสู่โลกภายนอก แต่เสน่ห์เฉพาะตัวของทางตอนเหนือมักจะพาให้หนุ่มสาวเหล่านี้กลับมาบ้านเสมอ คุณจะเห็นรูปปั้นนักเดินทางกำลังกลับบ้านบ่อย ๆ บนเส้นทางไปนอร์ธแลนด์",
  str_aircraft_tactic_info22103 = "ภูมิอากาศที่เป็นเอกลักษณ์ของนอร์ธแลนด์: พื้นที่ส่วนใหญ่ของนอร์ธแลนด์ถูกปกคลุมด้วยน้ำแข็งและหิมะที่แข็งตลอดทั้งปี มีเพียงไม่กี่แห่งเท่านั้นที่อากาศอบอุ่นและมีกลิ่นจาง ๆ ของช่วงต้นฤดูใบไม้ผลิโชยพลิ้วมากับหิมะ",
  str_aircraft_tactic_info22104 = "ภูเขานอร์ธแลนด์: นอร์ธแลนด์ตั้งอยู่บริเวณแถบสุดขอบโลกซึ่งเป็นเทือกเขาที่สูงที่สุดในทวีป ว่ากันว่าสามารถเข้าสู่ดินแดนรัตติกาลนิรันดร์ได้ผ่านภูเขาลูกนี้ ทว่าข่าวลือนี้ยังเป็นแค่ตำนานเท่านั้น ผู้อยู่อาศัยในนอร์ธแลนด์แทบไม่เคยเดินทางลึกเข้าไปในสุดขอบโลกเลยเพราะเคารพและกลัวอันตรายมากมายที่ซ่อนอยู่ในแนวเทือกเขา",
  str_aircraft_tactic_info23101 = "วัสดุสร้างบ้านของนอร์ธแลนด์: วัสดุสิ่งปลูกสร้างที่ใช้ในนอร์ธแลนด์ค่อนข้างธรรมดาและมีแร่ดิบกับไม้ที่ผ่านการแปรรูปเล็กน้อย\nเป็นหลัก แต่ก็ไม่ได้แปลว่าบ้านนอร์ธแลนด์จะขาดคุณค่าด้านความสวยงามแต่อย่างใด อันที่จริงลักษณะแบบธรรมชาติของพวกเขาเป็นตัวอย่างของความงดงามที่บริสุทธิ์ ไร้การแต่งแต้ม",
  str_aircraft_tactic_info23102 = "สถาปัตยกรรมนอร์ธแลนด์: สิ่งก่อสร้างของนอร์ธแลนด์มักจะสูงและแคบ มีเสาสูง ๆ เรียงราย โดยไม่จำกัดวามสูงและพื้นที่ของจุดสูงสุด สามารถสร้างให้ใหญ่และสูงได้ตามความต้องการ",
  str_aircraft_tactic_info23103 = "การสร้างบ้านในนอร์ธแลนด์: โดยปกติผู้สร้างจะใช้รถม้าในการขนส่งไม้สำหรับก่อสร้าง บางครั้งก็ใช้ลูมินาติกส์เข้าช่วย เช่น อาจใช้น้ำแข็งสร้างเป็นกรอบหรือใช้ลูมินาตัดหิน",
  str_aircraft_tactic_info23104 = "ธรณีสัณฐานของนอร์ธแลนด์: นอร์ธแลนด์ล้อมรอบด้วยป่าที่เป็นทั้งแนวป้องกันทางธรรมชาติและเป็นแหล่งทรัพยากรธรรมชาติที่อุดมสมบูรณ์อย่างไม่มีวันหมดสิ้น",
  str_aircraft_tactic_info24101 = "ขนมปังขี้เลื่อย: อาหารปันส่วนที่จัดทำขึ้นเพื่อรับมือในเหตุสงครามและแจกจ่ายให้ทหารจนปัจจุบัน ขนมปังรสชาติประหลาดแต่เสริมสร้างโภชนาการให้ทหารทั่วไปได้เพียงพออย่างน่าประหลาดใจ สหพันธรัฐอิลลูมินามักจะเรียกอาหารปันส่วนนี้ว่า \"ขนมปังขี้เลื่อย\" เพราะเป็นที่สงสัยว่ามีส่วนผสมของสิ่งสกปรกที่กินได้ตามแนวชายแดนที่คล้ายคลึงกับขี้เลื่อย",
  str_aircraft_tactic_info24102 = "ช็อกโกแลต: ผู้อยู่อาศัยในภูมิภาคที่หนาวกว่ามักจะคุ้นเคยกับขนมที่ทำโดยการถนอมอาหารมากกว่าอยู่แล้ว ดังนั้นช็อกโกแลตที่มีรสหวานกลมกล่อมจึงเป็นหนึ่งในผลิตภัณฑ์นำเข้าเพียงไม่กี่อย่างที่ได้รับ\nความนิยมในนอร์ธแลนด์",
  str_aircraft_tactic_info24103 = "ปศุสัตว์ในนอร์ธแลนด์: ผู้คนในนอร์ธแลนด์เลี้ยงสัตว์ที่เชื่อง เช่น กวาง แกะและสัตว์ปีก กระนั้นสัตว์ดุร้ายบางประเภทก็มักจะปรากฏบนเมนูอาหารของพวกเขา เช่น หมีน้ำตาลและหมูป่าที่มีแต่นักล่าเท่านั้นที่จะล่าได้",
  str_aircraft_tactic_info24104 = "การตกปลา: บริเวณชายฝั่งทะเลของนอร์ธแลนด์เหมาะสำหรับการตกปลา เช่นเดียวกับพื้นที่ภายในดินแดนที่เลียบแม่น้ำและทะเลสาบ ออโรเรียนของนอร์ธแลนด์ไม่ล่าสัตว์ในทะเลสาบกระจกเงาเนื่องจากถือว่าเป็นพื้นที่ศักดิ์สิทธิ์\nอันเนื่องมาจากตำนานและประเพณีที่ยาวนานนับศตวรรษ",
  str_aircraft_tactic_info25101 = "เกลือ: เกลือบริโภคพื้นฐานที่สกัดจากทะเลนอร์ธแลนด์โดยชาวบ้านในท้องถิ่น เกลือที่เกินความจำเป็นจะถูกนำไปค้าขายแลกเปลี่ยนเป็นสิ่งของจิปาถะ โดยทั่วไปแล้ว คนในท้องถิ่นจะใช้เกลือน้อยกว่าคนในภูมิภาคอื่นเพราะอยู่ใกล้ทะเลมากกว่าและสามารถเสริม\nการบริโภคเกลือด้วยการกินปลาทะเลได้",
  str_aircraft_tactic_info25102 = "การแจกจ่ายเกลือ: การค้าขายเกลือถือว่าค่อนข้างน้อยในนอร์ธแลนด์ พลเมืองที่อาศัยอยู่บริเวณชายฝั่งสามารถจัดหาเกลือได้ง่ายมากแต่ไม่ค่อยชอบใช้เกลือทำอาหาร\nนัก เนื่องจากวัตถุดิบที่ได้จากทะเลมีรสชาติมากพอแล้ว ผู้คนที่อาศัยอยู่ภายในดินแดนมีความต้องการเกลือสูงกว่า แต่ช่องทางการจัดจำหน่ายสินค้าที่นอร์ธแลนด์ค่อนข้างล้าหลัง หมายความว่าผู้คนมักต้องไปถึงริมทะเลเพื่อซื้อเกลือ",
  str_aircraft_tactic_info25103 = "ทะเลสาบน้ำเค็ม: มีทะเลสาบน้ำเค็มขนาดใหญ่หลายแห่งในนอร์ธแลนด์ นักวิชาการมั่นใจว่าทะเลสาบเหล่านี้เป็นทะเลร้างที่เกิดขึ้นใหม่เนื่องจากการเปลี่ยนแปลงโครงสร้าง\nของทวีปโบราณ",
  str_aircraft_tactic_info25104 = "หมาป่าหิมะ: นักล่าดุร้ายในนอร์ธแลนด์นี้ใช้ชีวิตเป็นฝูงและเหมือนจะฉลาดกว่าสัตว์ร้ายทั่วไป",
  str_aircraft_tactic_info26101 = "หุบเขาน้ำแข็งยอดสน: หนึ่งในภูมิภาคที่เป็นแนวหน้าของนอร์ธแลนด์ มีฐานรักษาการณ์สร้างไว้ที่นี่เพื่อป้องกันอิคลิพไซท์ผู้บุกรุก",
  str_aircraft_tactic_info26102 = "หมู่บ้านมหัศจรรย์: หมู่บ้านนี้ตั้งอยู่บริเวณชายแดนนอร์ธแลนด์ มีจำนวนประชากรค่อนข้างมากจนสามารถเป็นเมืองขนาดเล็กได้",
  str_aircraft_tactic_info26103 = "ป่าสนนอร์ธแลนด์: เนินเขานี้มีคริสตัลที่ไม่ได้นำมาใช้งานอยู่จำนวนมาก ชาวบ้านจะแบ่งกลุ่มทั้งขนาดใหญ่และเล็กกระจายไปตามที่ราบระหว่างเนินเขา",
  str_aircraft_tactic_info26104 = "ป่าลู่ลม: ตั้งอยู่ทางใต้ของนอร์ธแลนด์ ป่าแห่งนี้มีสภาพอากาศอบอุ่นตลอดปีและเป็นบ้านของพืชและสัตว์นานาชนิด",
  str_aircraft_tactic_info27101 = "ลูมินาติกส์ในนอร์ธแลนด์: ออโรเรียนในนอร์ธแลนด์ยอมรับความสำคัญของธรรมชาติในทุกสิ่งด้วยความเข้าใจในกระบวนการลูมินาพื้นฐานส่วนใหญ่ที่ธรรมชาติสร้างขึ้น สะท้อนกับสิ่งที่เป็นธรรมชาติและเข้าแทรกแซงโลกผ่านขอบเขตแห่งจินตนาการและการรับรู้ทางจิต",
  str_aircraft_tactic_info27102 = "ตัวกลางลูมินาติกส์นอร์ธแลนด์: ลูมินาติกส์มักต้องการตัวกลางแบบธรรมชาติแท้ ๆ สำหรับออโรเรียนในนอร์ธแลนด์ ตัวกลางที่ใช้กันมากที่สุดคือเครื่องมือที่ทำจากกิ่งไม้ และออโรเรียนบางรายก็สื่อผ่านสัตว์ได้ เมื่อเทียบกับพิธีในลูโมโพลิสแล้ว ลูมินาติกส์ในนอร์ธแลนด์เก่าแก่และสร้างผลลัพธ์พื้นฐานมากกว่า แต่มักจะทรงพลังกว่า",
  str_aircraft_tactic_info27103 = "ความเชื่อในนอร์ธแลนด์: ชาวนอร์ธแลนด์เชื่อว่าทุกอย่างมีจิตวิญญาณและสามารถสื่อสารกับทุกอย่างได้ ไม่ว่าจะเป็นสัตว์ พืช สภาพแวดล้อมหรือกระทั่งปรากฏการณ์ก็ตาม",
  str_aircraft_tactic_info27104 = "ความเชื่อและธรรมาภิบาล: ความเชื่อในนอร์ธแลนด์ไม่ได้เป็นไปตามโครงสร้างที่ถูกจัดระเบียบอย่างเคร่งครัด ดังนั้นจึงไม่มีผลกระทบกับการปกครองของวงศ์ตระกูลราชวงศ์ อันที่จริงแล้วธรรมาภิบาลของราชวงศ์นอร์ธแลนด์มักจะไม่ข้องเกี่ยวกับศาสนาเท่าไรนัก ก่อเป็นโครงสร้างที่แยกออกมาจนเกือบจะขนานไปกับระบบความเชื่อที่นิยมกันเลยทีเดียว",
  str_aircraft_tactic_info28101 = "ลูมินาติกส์ในอิลลูมินา: ลูมินาติกส์ที่สหพันธรัฐอิลลูมินาใช้นั้นต่างจากที่ภูมิภาคอื่นใช้และมุ่งเน้นในด้านวิศวกรรมมากกว่า โดยการใช้ตัวกลางจักรกลที่พัฒนาด้วยเทคโนโลยี ผู้ใช้งานสามารถร่ายคาถาได้โดยไม่ต้องเพ่งจิต",
  str_aircraft_tactic_info28102 = "สุนัขลากเลื่อน: ผู้อยู่อาศัยในนอร์ธแลนด์มักจะเลี้ยงสุนัขสายพันธุ์นี้ พวกมันลากเลื่อนได้อย่างคล่องแคล่วและตามติดเจ้าของเวลาออกล่า อีกทั้งยังเป็นตัวเลือกที่นิยมกันเวลาเลือกสัตว์เลี้ยงอีกด้วย",
  str_aircraft_tactic_info28103 = "ชีวิตประจำวันในนอร์ธแลนด์: ชีวิตประจำวันสำหรับชาวนอร์ธแลนด์นั้นแทบจะเหมือนกัน เริ่มทำงานตอนอาทิตย์ขึ้นและเลิกตอนอาทิตย์ตก ทุกคนมีหน้าที่ที่ต้องทำ ไม่ว่าจะเป็นการทำฟาร์ม เลี้ยงสัตว์ ออกล่าหรืองานใช้แรงงาน ผู้อาวุโสมักจะดูแลเด็กอยู่ที่บ้านและถ่ายทอดความรู้ทั้งหมดที่พวกเขามี",
  str_aircraft_tactic_info28104 = "การขนส่งด้วยตัวเอง: การขนส่งรูปแบบที่นิยมที่สุดในนอร์ธแลนด์คือขนส่งด้วยตัวเอง โชคดีที่ออโรเรียนมากมายใช้ลูมินาติกส์ช่วยเหลือในเรื่องนี้ได้",
  str_aircraft_tactic_info29101 = "การรวมตัวในวันเทศกาล: ผู้อยู่อาศัยในนอร์ธแลนด์ใช้ชีวิตเรียบง่าย เป็นอิสระจากความต้องการ ส่วนใหญ่แล้วพวกเขาแทบจะไม่แสวงหาความบันเทิงและแทบจะไม่มีกิจกรรมทางสังคมเลย มีเพียงช่วงเทศกาลเท่านั้นที่ทุกคนมารวมตัวและแบ่งปันเรื่องราวที่น่าสนใจทั้งหมดที่ได้ทำในช่วงที่\nผ่านมา",
  str_aircraft_tactic_info29102 = "กิจกรรมทางสังคม: ในช่วงเทศกาล เช่น ปีใหม่ ผู้คนมักจะชอบมานั่งล้อมวง พูดคุย ร้องเพลงและแข่งเล่าเรื่อง หรือไปปิกนิกในป่าใกล้เคียง พวกผู้ชายมักจะจัดปาร์ตี้ล่าสัตว์",
  str_aircraft_tactic_info29103 = "อาหารขึ้นชื่อ: ของขึ้นชื่อของนอร์ธแลนด์ส่วนใหญ่จะเป็นของหวานที่มักจะเสิร์ฟโดยราชวงศ์ในยามรับรองแขก นอกจากนี้ยังมีอาหารทะเลมากมายบนโต๊ะอาหาร เช่น แมวน้ำย่างและเนื้อฉลามหมัก",
  str_aircraft_tactic_info29104 = "เครื่องดื่มมึนเมา: เครื่องดื่มมึนเมาประจำท้องถิ่นได้แก่ไวน์น้ำผึ้งและจิน ชื่อของเครื่องดื่มมักจะเกี่ยวกับน้ำแข็งและหิมะ",
  str_aircraft_tactic_info30101 = "ชายแดนปิด: ถึงนอร์ธแลนด์จะทำการค้ากับนครรัฐอื่นแต่ก็ยังค่อนข้างแยกตัวจากโลก ผู้คนมากมายที่อาศัยอยู่ในหมู่บ้านและเมืองของนอร์ธแลนด์แทบไม่มีโอกาสได้พบปะผู้คนภายนอก\nเลย ดังนั้นพวกเขาจึงต้อนรับผู้มาเยือนด้วยใจและสนใจฟังข่าวเกี่ยวกับโลกภายนอกมาก เพราะเหตุนี้ผู้คนจึงมองว่าชาวนอร์ธแลนด์ทั้งอบอุ่นและใจดี",
  str_aircraft_tactic_info30102 = "อุณหภูมิในนอร์ธแลนด์: ผู้คนในนอร์ธแลนด์มีนิสัยเรียบง่ายและจิตใจบริสุทธิ์ ด้วยหลายปีที่แยกตัวออกไปและพึ่งพาตนเอง แต่พวกเขาก็มีความหัวดื้อและไม่ยอมรับการเปลี่ยนแปลงด้วยเช่นกัน ตัวอย่างเช่น กลัวแนวความคิดใหม่ที่ทำให้พวกเขาปรับตัวเข้ากับการใช้ชีวิตที่รวดเร็วและมุ่งเน้นเชิงพาณิชย์แบบอัมบราตันได้ยาก",
  str_aircraft_tactic_info30103 = "การรับรู้ด้านเวทมนตร์: ผู้คนในนอร์ธแลนด์ไม่แปลกใจกับสิ่งของหรือเหตุการณ์ที่เหลือเชื่อโดยง่ายและถึงขั้นชินกับปรากฏการณ์เหล่านั้นด้วยซ้ำ เช่น เมื่อพบกวางพูดได้ ชาวนอร์ธแลนด์ก็จะพูดกับกวางเป็นปกติโดยไม่เคลือบแคลงใจกับเหตุการณ์แปลกประหลาดนั้นเลย",
  str_aircraft_tactic_info30104 = "การค้าขายของนอร์ธแลนด์: นอร์ธแลนด์อยู่ติดกับทะเล ดังนั้นเรือจึงจอดเทียบท่าเพื่อนำเข้าสินค้าแปลกใหม่เป็นประจำ ถึงอย่างนั้นประชาชนนอร์ธแลนด์กลับไม่สนใจสินค้าฟุ่มเฟือย พ่อค้าแม่ขายก็มักจะอยากออกจากนอร์ธแลนด์ให้ได้เร็วที่สุดเพื่อไปเยี่ยมเยือนนครรัฐอื่นในแอสตรา",
  str_aircraft_tactic_info31101 = "กลุ่มค้นหา: หมู่บ้านต่าง ๆ ในนอร์ธแลนด์จะตั้งกลุ่มค้นหาเมื่อมีความต้องการเพื่อตามจับอิคลิพไซท์ที่มาบุกรุกและตามหาออโรเรียนที่หายไป รวมถึงเหตุสำคัญอื่นด้วย ขนาดของกลุ่มค้นหานี้ไม่แน่นอนและมักจะมีสมาชิกสี่ถึงหกคน ขอบเขตการทำงานของกลุ่มเหล่านี้มักจะอยู่บริเวณรอบหมู่บ้าน แม้ว่าบางทีจะเน้นในจุดที่พบเห็นอิคลิพไซท์ก็ตาม ผู้อาวุโสขอให้ชายหนุ่มช่วยเหลือ รวมถึงนักล่าหรือคนที่คุ้นเคยกับป่าเขาก็ได้รับหน้าที่ให้นำทางด้วย",
  str_aircraft_tactic_info31102 = "การศึกษาในนอร์ธแลนด์: นอร์ธแลนด์ไม่มีระบบการศึกษาที่เป็นมาตรฐานของตัวเองและความรู้ที่จำเป็นทั้งหมดถ่ายทอดด้วยวิธีการบอกต่อ",
  str_aircraft_tactic_info31103 = "กฎหมายนอร์ธแลนด์: นอร์ธแลนด์ไม่มีตัวบทกฎหมายที่เขียนเป็นลายลักษณ์อักษร ความยุติธรรมมักขึ้นอยู่กับศีลธรรมปกติของชาวบ้านที่มีต่อกัน ขุนนางท้องถิ่นหรือสถาบันปกครองก็ถูกเรียกไปไกล่เกลี่ยข้อพิพาทได้",
  str_aircraft_tactic_info31104 = "การปกครองนอร์ธแลนด์: ชาวนอร์ธแลนด์ไม่ชอบให้คนนอกเข้ามาแทรกแซงการบริหารการตั้งถิ่นฐานของพวกเขา เพราะทุกเมืองและทุกหมู่บ้านล้วนมีประวัติเฉพาะตัวที่ยาวนานเป็นพันปี พวกเขาเชื่อว่าการปฏิบัติในปัจจุบันนั้นเพียงพอแล้ว",
  str_aircraft_tactic_info32101 = "ตำนานนอร์ธแลนด์: ว่ากันว่าออโรเรียนดั้งเดิมถือกำเนิดที่นอร์ธแลนด์ พวกเขาอาบแสงออโรราแล้วรับพลังอันสูงส่งไว้ ออโรเรียนของนอร์ธแลนด์ผูกพันอย่างลึกซึ้งกับดินแดนของตนและไม่คำนึงถึงการเปลี่ยนแปลงอันยิ่งใหญ่ของโลกภายนอก พวกเขาถือว่ามาตุภูมินี้เป็นแผ่นดินบริสุทธิ์แห่งแรกและแห่งสุดท้ายเสมอ",
  str_aircraft_tactic_info32102 = "นอร์ธแลนด์ในปัจจุบัน: ในขณะที่ชายแดนเริ่มเปิดอย่างช้า ๆ นอร์ธแลนด์กลายเป็นที่รู้จักต่อคนภายนอกมากขึ้น กระทั่งผู้อาศัยในทะเลทรายเรดีเซลก็ยังได้ยินข่าวลือเกี่ยวกับที่นี่ นครรัฐอื่นในทวีปก็พบชาวนอร์ธแลนด์เดินทางไปเป็นครั้งคราวและยินดีกับโอกาสที่จะได้ซื้อสินค้าทุกอย่างที่มาจากนอร์ธแลนด์ ถึงอย่างนั้น การแยกตัวออกไปเป็นระยะเวลานานของนอร์ธแลนด์ก็สร้างความสงสัยไปทั่วดินแดน โดยเฉพาะในสายตาของคนธรรมดา นอร์ธแลนด์ก็ยังเป็นสถานที่ปริศนาที่มีเวทมนตร์และความลับต่าง ๆ มากมาย",
  str_aircraft_tactic_info32103 = "ผู้ปกครองนอร์ธแลนด์: ในปัจจุบัน เบธเลเฮมเป็นสมาชิกแต่เพียงผู้เดียวของราชวงศ์นอร์ธแลนด์ เธอเป็นผู้ปกครองเพียงหนึ่งเดียวในใจของชาวนอร์ธแลนด์ด้วยลูมินาติกส์ที่ทรงพลังและสืบเชื้อสายราชวงศ์ ชาวนอร์ธแลนด์ทุกหมู่เหล่าเคารพเบธเลเฮมเป็นอย่างมากและไม่มีใครกล้าคิดขัดขืนคำสั่งหรือสงสัยในการตัดสินใจของเธอเลย",
  str_aircraft_tactic_info32104 = "ราชวงศ์นอร์ธแลนด์: ราชวงศ์นอร์ธแลนด์เป็นผู้ปกครองที่ให้สัตย์สาบานและคุ้มครองนอร์ธแลนด์ ราชวงศ์มีอำนาจที่หามีใครเทียบได้ซึ่งสืบทอดมาจากรุ่นสู่รุ่นและปกครองมานับพันปี",
  str_aircraft_tactic_info33101 = "หนังสือนอร์ธแลนด์: หนังสือเป็นสิ่งที่มีน้อยในนอร์ธแลนด์ เพราะผู้คนมักจะถ่ายทอดความรู้โดยการบอกเล่าจากปาก หรือผ่านงานแกะสลัก ผูกเงื่อนเชือก และแผ่นไม้ หรือถ้าจะมีก็มักจะเป็นกระดาษหนัง",
  str_aircraft_tactic_info33102 = "เฟอร์นิเจอร์: นอร์ธแลนด์มีสไตล์การตกแต่งภายในของตัวเองโดยอยู่บนพื้นฐานของความเรียบง่ายมากกว่า\nความหรูหรา แม้ดูมีความถ่อมตนแต่สไตล์นี้ก็สร้างความงดงามที่น่าสุนทรีย์ได้ด้วยการจัดวาง\nสิ่งของ",
  str_aircraft_tactic_info33103 = "ดนตรี: ดนตรีในนอร์ธแลนด์มักเป็นที่ชื่นชอบของเด็กเป็นส่วนใหญ่ ดังนั้นแนวดนตรีในภูมิภาคนี้จะมีความเบิกบานและจังหวะเร็ว ทำให้เหมาะมากสำหรับประกอบนิทาน",
  str_aircraft_tactic_info33104 = "กองทหารนอร์ธแลนด์: นอร์ธแลนด์ไม่มีกองทัพที่ตายตัว เพราะพื้นที่ห่างไกลนี้ไม่ข้องแวะกับการดำเนินงานของนครรัฐต่าง ๆ ในแอสตราเลย แต่ละพื้นที่จะจัดตั้งทหารอาสาป้องกันของตนเองโดยมักจะไม่เกินหนึ่งพันนาย",
  str_aircraft_tactic_info40101 = "การส่งจดหมายโต้ตอบระหว่างอัมบราตันกับทะเลทรายเรดีเซล: โดยทั่วไปแล้ว ผู้คนมักจะฝากให้คนรู้จักที่ไว้ใจได้เป็นคนส่งจดหมาย เวลาส่งนั้นก็แตกต่างกันไปอย่างมาก ปกติแล้วการเดินทางขาเดียวระหว่างสถานที่ทั้งสองแห่งใช้เวลาประมาณ 1 เดือน แต่ถ้าใช้บริการของมืออาชีพอย่างสหภาพผู้ส่งสาร ก็สามารถลดเวลาส่งได้มาก ซึ่งบางกรณีอาจใช้เวลาเพียง 1 สัปดาห์เท่านั้น",
  str_aircraft_tactic_info40102 = "เรดีเซล เวรนช์: กลุ่มคนพเนจรและอาชญากรเร่ร่อนที่อาศัยอยู่ในทะเลทรายเรดีเซล แต่เดิมพวกเขาเป็นส่วนหนึ่งของทหารหน่วยหน้าจากอิลลูมินา รับหน้าที่ขุดค้นและสำรวจเมืองใต้ดิน หลังจากการสูญเสียอันสุดแสนสะเทือนใจที่ดินแดนลับ พวกเขาได้ตัดความสัมพันธ์กับสหพันธรัฐอิลลูมินาและลี้ภัยมาอาศัยในทะเลทรายเรดีเซล เมื่อเวลาผ่านไป พวกเขาก็ค่อย ๆ กลายเป็นกลุ่มโจรเร่ร่อนอย่างที่รู้จักกันในปัจจุบัน",
  str_aircraft_tactic_info40103 = "วัฒนธรรมของเรดีเซล เวรนช์: เสรีภาพในระดับที่เข้าใกล้ความเป็นอนาธิปไตยเต็มขั้นนั้นเป็นคุณลักษณะสำคัญของวัฒนธรรมเรดีเซล เวรนช์ การเอาชีวิตรอดคือเป้าหมายหลัก ส่วนเรื่องอื่น ๆ เป็นเพียงสิ่งที่เติมแต่งสีสันให้ชีวิต",
  str_aircraft_tactic_info40104 = "ลำดับขั้นภายในเรดีเซล เวรนช์: ไม่มี",
  str_aircraft_tactic_info40201 = "โฮเวอร์คราฟต์: วิธีเดินทางหลักของทีมหน่วยหน้าจากอิลลูมินาในระหว่างการสำรวจ แม้จะไม่สะดวกสบาย แต่พาหนะที่แสนมีประโยชน์นี้ก็ใช้บุกป่าฝ่าดงไปยังภูมิประเทศสมบุกสมบันได้หลากหลายรูปแบบ เนื่องจากอิลลูมินาให้ความสำคัญอย่างยิ่งกับการสำรวจและวิจัย โฮเวอร์คราฟต์จึงเป็นสิ่งที่รับใช้สหพันธ์เป็นอย่างดี โดยการบรรทุกทีมหน่วยหน้าเข้าไปยังส่วนลึกของพื้นที่ที่คนทั่วไปเข้าไม่ถึง",
  str_aircraft_tactic_info40202 = "โครงสร้างของโฮเวอร์คราฟต์: โฮเวอร์คราฟต์เป็นผลงานต่อยอดจากดีไซน์ของรถบรรทุกธรรมดา มีการติดตั้งระบบโช้คลมที่ทนทานเพื่อให้ลอยตัวและเดินทางไปยังภูมิประเทศหลากหลาย (เนินทราย หนองน้ำ และอื่น ๆ...)",
  str_aircraft_tactic_info40203 = "การทำงานของโฮเวอร์คราฟต์: ภายใต้สถานการณ์ปกติ กฎการขับโฮเวอร์คราฟต์นั้นก็ไม่ต่างจากการขับรถบรรทุกธรรมดา แต่ถ้าหากต้องลอยตัว โฮเวอร์คราฟต์จะต้องอยู่สูงจากพื้นไม่เกินครึ่งเมตร นอกจากนี้ เนื่องจากโฮเวอร์คราฟต์จะโคลงเคลงอย่างมากขณะลอยตัว จึงห้ามใช้ขนส่งอุปกรณ์ความแม่นยำสูงที่มีขนาดใหญ่",
  str_aircraft_tactic_info40204 = "ระบบขับเคลื่อนของโฮเวอร์คราฟต์: เพื่อรักษาความสามารถในการลอยตัว โฮเวอร์คราฟต์ใช้เครื่องหมุนเวียนอากาศพิเศษเพื่อเปลี่ยนถ่ายลมในโช้คลมเป็นระยะ เมื่อเดินทางผ่านทะเลทราย ก็จะต้องติดตั้งพัดลมพิเศษเพื่อขจัดทรายและสิ่งสกปรกต่าง ๆ",
  str_aircraft_tactic_info40301 = "พายุทราย: พายุทรายเป็นปรากฏการณ์ธรรมชาติที่พบได้ทั่วไปในทะเลทรายเรดีเซล โดยทั่วไปเกิดทุก 24 ถึง 48 ชั่วโมง ผู้อยู่อาศัยในทะเลทรายคุ้นเคยกับการหลบพายุทรายในหลุมทรายหรือที่กำบังชั่วคราวอื่น ๆ เป็นอย่างดี ปกติแล้วสายลมและทรายที่โหยหวนไม่ส่งผลอะไรกับชีวิตประจำวันของพวกเขามากนัก",
  str_aircraft_tactic_info40302 = "ความแตกต่างของอุณหภูมิ: ทะเลทรายเรดีเซลส่วนใหญ่มีอุณหภูมิสูงกว่า 50°C ในเวลากลางวัน และลดลงเหลือ 5°C ในเวลากลางคืน ส่วนทางทิศเหนือที่หนาวกว่าเล็กน้อย อุณหภูมิเวลากลางวันอาจสูงถึงประมาณ 40°C และลดลงต่ำกว่า 0°C ในเวลากลางคืน",
  str_aircraft_tactic_info40303 = "นิคมทะเลทรายของชาวออโรเรียน: ออโรเรียนส่วนใหญ่ในทะเลทรายเรดีเซลมักจะอาศัยอยู่ในเมืองโอเอซิส และมีส่วนน้อยที่เลือกอาศัยอยู่ตรงชายแดนทะเลทราย แม้กลุ่มคนเร่ร่อนแห่งทะเลทรายเหล่านี้จะเดินทางตลอดปี แต่ก็ไม่มีที่ไปมากนักเพราะปัญหาขาดแคลนน้ำ",
  str_aircraft_tactic_info40304 = "มาตรการป้องกัน: บ้านเรือนแต่ละหลังจะมี \"รังทราย\" ใต้ดินของตัวเองเพื่อหลบพายุทราย โดยทั่วไปแล้วพวกเขาจะห่อเครื่องเรือน อุปกรณ์ และข้าวของส่วนตัวอื่น ๆ ไว้ในถุงพลาสติกหรือผ้าเพื่อปกป้องจากแสงแดดและทราย",
  str_aircraft_tactic_info40401 = "ร้านขายของมือสอง: ร้านค้าที่มากด้วยความมหัศจรรย์และมนตร์วิเศษซึ่งกระจายอยู่ทั่วทะเลทราย เราไม่มีทางรู้ได้เลยว่าอะไรจะรออยู่ข้างใน อาจเป็นสิ่งที่ปรารถนาที่สุดในชีวิต หรือไม่ก็เป็นเซอร์ไพรส์ที่คาดไม่ถึง",
  str_aircraft_tactic_info40402 = "ของนำเข้าจากทะเลทราย: ขยะในสายตาคนคนหนึ่งอาจเป็นสมบัติมีค่าสำหรับอีกคน\nและร้านขายของมือสองนั้นก็มักจะพบ \"สมบัติ\" เหล่านั้นอยู่เสมอ\nเราอาจพบของมีค่าทุกรูปแบบในลานขยะหรือกระจายตัวอยู่ทั่วทะเลทรายอันแห้งแล้ง\nบางครั้งมูลค่าของสมบัติพวกนี้ก็วัดได้ด้วยความยินดีซื้อเท่านั้น",
  str_aircraft_tactic_info40403 = "ของเหลือราคาถูก: สมาชิกของเรดีเซล เวรนช์ มักจะเจอของแปลกตาไม่เหมือนใคร และมีแนวโน้มจะขายทิ้งให้ร้านขายของมือสองถ้าไม่ได้ใช้ ดังนั้นร้านขายของมือสองเหล่านี้จึงทำหน้าที่เป็นโรงรับจำนำของชาวทะเลทรายโดยปริยาย",
  str_aircraft_tactic_info40404 = "งานประดิษฐ์ทำเอง: ร้านขายของมือสองมีชื่อเสียงอันร้ายกาจในเรื่องการประกอบใหม่หรือดัดแปลงของที่หามาได้ด้วยสิ่งละอันพันละน้อยที่กองอยู่ในเวิร์กช็อป โดยทั่วไปแล้วสิ่งประดิษฐ์พวกนี้คุณภาพต่ำกว่ามาตรฐานของผู้ผลิต แต่ถึงกระนั้นก็มีประโยชน์ในสถานที่ที่ยากลำบากและไม่อาจคาดเดาอย่างทะเลทรายเรดีเซล",
  str_aircraft_tactic_info40501 = "การตั้งแก๊งโจรทะเลทราย: สมาชิกแก๊งโจรส่วนใหญ่ก็คือผู้คนเร่ร่อนแห่งทะเลทรายเรดีเซล พวกเขาใช้ชีวิตโดยการค้นหาของมีค่าไปทั่วทะเลทราย นอกจากนี้ยังซุ่มโจมตีนักเดินทาง บางครั้งถึงขั้นรวมกลุ่มกันปล้นคาราวานทหารของอิลลูมินา",
  str_aircraft_tactic_info40502 = "วิธีก่อคดี: แก๊งโจรทะเลทรายมักจะปล้นคนอ่อนแอกว่าและหวาดกลัวคนแข็งแกร่ง พวกเขาไม่มีหลักการหรือความยับยั้งชั่งใจ ดังนั้นเรื่องศีลธรรมก็อย่าหวัง ทั้งความคิดและการกระทำของคนเหล่านี้เห็นแก่ตัวอย่างหน้าไม่อาย",
  str_aircraft_tactic_info40503 = "แก๊งโจรกับเรดีเซล เวรนช์: แก๊งโจรทะเลทรายส่วนใหญ่หวาดกลัวเรดีเซล เวรนช์ เพราะเรดีเซล เวรนช์ ลงโทษกลุ่มโจรจนเข็ดหลาบ แค่พวกโจรได้พบเจอเรดีเซล เวรนช์ บ่อยครั้งที่ทั้งแก๊งจะหนีหัวซุกหัวซุน",
  str_aircraft_tactic_info40504 = "ชิ้นส่วนวิทยาการ: มักจะมีการขุดค้นพบชิ้นส่วนวิทยาการทั่วทะเลทรายเรดีเซล แม้ไม่มีใครแน่ใจว่าสิ่งเหล่านี้มีต้นกำเนิดจากไหนและมีหน้าที่อะไร แต่สิ่งเดียวที่ทุกคนแน่ใจก็คือ สิ่งเหล่านี้ขายในตลาดได้ราคาดีเสมอ",
  str_aircraft_tactic_info40601 = "วันลูโมโพลิส: วันลูโมโพลิสเป็นเทศกาลวันหยุดเพื่อเฉลิมฉลองการก่อตั้งเมืองลูโมโพลิส การเฉลิมฉลองนี้เป็นการแสดงแสนยานุภาพของลูโมโพลิสต่อสายตาชาวโลก และปลูกฝังความภาคภูมิใจในเกียรติยศให้แก่พลเมือง งานฉลองนี้ใช้ของประดับประดาที่หรูหราที่สุดเพื่ออวดความมั่งคั่งล้นเหลือของเมือง นอกจากนี้ยังมีการเชิญบุคคลสำคัญจากต่างแดนและแขกคนสำคัญต่าง ๆ มาเข้าร่วมงานเลี้ยงสุดอลังการซึ่งเป็นไฮไลต์สำคัญ",
  str_aircraft_tactic_info40602 = "ขนมในวันลูโมโพลิส: ในระหว่างเทศกาล ท้องถนนของลูโมโพลิสก็จะเต็มไปด้วยแผงขนมขบเคี้ยวที่ให้บริการฟรี ชาวเมืองลูโมโพลิสจะเตรียมพายผลไม้โฮมเมดและขนมแสนอร่อยอื่น ๆ มาแบ่งปันกันในงานฉลองอันยิ่งใหญ่",
  str_aircraft_tactic_info40603 = "วันลูโมโพลิส - กฎการเข้า/ออกเมือง: ในระหว่างเทศกาลจะมีการผ่อนปรนกฎการเข้าออกเมืองเพื่อให้ชาวต่างแดนได้มีโอกาสร่วมงานฉลองมากขึ้น ผู้มาเยือนไม่ต้องกังวลเรื่องค่าใช้จ่ายระหว่างเทศกาลนี้ เพราะสินค้าและบริการส่วนใหญ่จะไม่คิดเงินในวันลูโมโพลิส",
  str_aircraft_tactic_info40604 = "งานเลี้ยงไร้เสียง: การประมูลที่เป็นเอกลักษณ์ไม่เหมือนใครในอัมบราตัน ในฉากหน้าแล้วไม่ต่างจากงานเลี้ยงทั่วไป แขกในงานจะได้เพลิดเพลินกับอาหารและความบันเทิงรสเลิศ แต่เป็นที่รู้กันว่างานพิเศษนี้จะมีการทำธุรกรรมมูลค่ามหาศาลทุกรูปแบบเกิดขึ้น ซึ่งทั้งหมดนี้ดำเนินไปโดยไม่มีการเอ่ยปากคุยแม้แต่คำเดียว...",
  str_aircraft_tactic_info40701 = "แนวเพลง: แต่ละภูมิภาคมีสไตล์การฟังเพลงที่แตกต่างกันไปตามรสนิยมส่วนบุคคลและรสนิยมเชิงวัฒนธรรม เพลงที่ได้รับความนิยมในลูโมโพลิสมีความสง่างามและละเมียดละไม ส่วนทะเลทรายเรดีเซลก็จะนิยมเพลงที่เต็มเปี่ยมด้วยพลังงานความมุ่งมั่น เพลงของนอร์ธแลนด์นั้นเรียบง่ายแต่มีชีวิตชีวา ส่วนเพลงของสหพันธรัฐอิลลูมินาจะออกไปทางเศร้าหมองและเคร่งขรึม...",
  str_aircraft_tactic_info40702 = "เครื่องดนตรี: เครื่องดนตรีนั้นเป็นสิ่งที่เกี่ยวข้องกับสไตล์เพลงที่นิยมในแต่ละภูมิภาคอย่างแยกจากกันไม่ได้ ไวโอลิน เปียโน และออร์แกน เป็นเครื่องดนตรีที่มีอิทธิพลในแวดวงดนตรีของลูโมโพลิส ส่วนกีตาร์ไฟฟ้า เบส และกลองชุด เป็นสิ่งที่พบได้ทั่วไปและเป็นที่ชื่นชอบในผับของทะเลทรายเรดีเซล เครื่องลมไม้เป็นเครื่องดนตรีประจำบ้านของชาวนอร์ธแลนด์ ส่วนเครื่องลมทองเหลืองก็ได้รับความนิยมในสหพันธรัฐอิลลูมินา",
  str_aircraft_tactic_info40703 = "นักดนตรี: ลูโมโพลิสเป็นแหล่งรวมนักดนตรีที่มีชื่อเสียงมากที่สุด อาจเป็นเพราะหลายคนถือว่าไวโอลินและเปียโนเป็นเครื่องดนตรีที่สง่างามที่สุด ส่วนคนอายุน้อยก็จะชอบกีตาร์กับกลองชุดมากกว่าตัวเลือกอื่นที่ \"หรูหรา\" กว่า",
  str_aircraft_tactic_info40704 = "การเรียนดนตรี: แม้โรงเรียนหลายแห่งมีวิชาดนตรีในหลักสูตร แต่ก็ไม่มีสถาบันสอนดนตรีอย่างจริงจังในระดับมืออาชีพสำหรับนักดนตรีที่มุ่งมั่น ผู้ที่ต้องการประกอบอาชีพนักดนตรีควรไปศึกษาจากนักดนตรีที่ประสบความสำเร็จและมีชื่อเสียง",
  str_aircraft_tactic_info40801 = "ขบวนคอนวอยของอิลลูมินา: ขบวนคอนวอยของอิลลูมินาแต่ละขบวนประกอบด้วยรถบรรทุกขนเสบียง 2 ถึง 4 คัน แต่ละคันต้องการคนขับ 2 คน นอกจากนี้ยังมีการมอบหมายมอเตอร์ไซค์ประกบข้างอย่างน้อย 3 คันเพื่อรักษาความปลอดภัยให้รถบรรทุกแต่ละคัน",
  str_aircraft_tactic_info40802 = "เส้นทางขนส่งของคอนวอย: โดยทั่วไปคอนวอยมีหน้าที่รับผิดชอบในการขนส่งเสบียงระหว่างเมืองใต้ดินหลายแห่ง เนื่องจากข้อจำกัดทางกายภาพของรถบรรทุก เส้นทางการขนส่งจึงต้องเป็นถนนที่ค่อนข้างกว้าง และมีขบวนคอนวอยไม่กี่ขบวนที่ทำงานขนส่งนอกเส้นทางดังกล่าว",
  str_aircraft_tactic_info40803 = "วิธีการขนส่ง: รถบรรทุก \"แกซ\" เป็นพาหนะที่สหพันธรัฐอิลลูมินานิยมใช้เพื่อการขนส่งเชิงอุตสาหกรรม กำลังสูง มีประสิทธิภาพ และผลิตเป็นจำนวนมากได้ง่าย รถบรรทุกขนาดมหึมานี้ค่อนข้าง \"อัปลักษณ์\" ในเชิงสุนทรียศาสตร์ แต่ประโยชน์ใช้สอยอันยอดเยี่ยมก็ไม่อาจปฏิเสธได้",
  str_aircraft_tactic_info40804 = "เสบียงที่ขนส่ง: โดยทั่วไปคอนวอยของสหพันธรัฐอิลลูมินาขนส่งแร่ที่ขุดมา ชิ้นส่วนอะไหล่ที่ผลิตในแกนน่อน และของใช้ประจำวัน นอกจากนี้ คอนวอยมักจะได้รับหน้าที่ขนส่งอาวุธยุทโธปกรณ์ ซึ่งงานดังกล่าวจะถูกปกปิดเป็นความลับจากคนนอก",
  str_aircraft_tactic_info40901 = "การแต่งงานในอัมบราตัน: การแต่งงานในอัมบราตันไม่มีกฎเกณฑ์อะไรควบคุมเท่าไรนักและไม่จำเป็นต้องมีการรับรองใด ๆ สำหรับสมาชิกของกลุ่มอาชญากรต่าง ๆ ก็มักจำเป็นต้องได้รับการเห็นชอบจากหัวหน้ากลุ่ม ส่วนถ้าเป็นชาวเมืองทั่วไป แค่ได้รับความยินยอมจากพ่อแม่ของทั้งสองฝ่ายก็เพียงพอแล้ว",
  str_aircraft_tactic_info40902 = "พิธีแต่งงานของอัมบราตัน: พิธีแต่งงานมักจะเป็นโอกาสสำคัญที่ใหญ่โตหรูหรา พ่อแม่ของคู่แต่งงานใหม่จะมอบของขวัญราคาแพงเพื่อเป็นสัญลักษณ์แทนการยอมรับการสมรส",
  str_aircraft_tactic_info40903 = "ซุ้มประตูดอกไม้: ประตูที่ตกแต่งด้วยดอกไม้อย่างงดงามเพื่อพิธีสมรสในอัมบราตัน การเดินข้ามผ่านประตูดอกไม้นี้เป็นสัญลักษณ์แทนการเริ่มต้นชีวิตคู่อันเป็นนิรันดร์ เนื่องจากความงดงามและรายละเอียดของประตูแห่งนี้บ่งบอกถึงความสุขในอนาคตของคู่แต่งงานใหม่ การเลือกภาษาดอกไม้ที่เหมาะสมจึงสำคัญอย่างยิ่ง",
  str_aircraft_tactic_info40904 = "เกณฑ์การเลือกคู่ครอง: เกณฑ์ที่นิยมใช้ที่สุด (และบ่อยครั้งเป็นเรื่องสำคัญที่สุด) ในการเลือกคู่ครองที่อัมบราตันก็คือความมั่นคงทางการเงิน ซึ่งก็ไม่แปลกสำหรับสังคมที่เน้นการทำธุรกิจการค้าเพื่อหาเลี้ยงชีพ หากมีคำถามว่าระหว่างเงินกับความรักสิ่งใดสำคัญกว่ากัน เราก็ควรจำไว้ว่าในอัมบราตัน เงินนั้นซื้อได้แม้กระทั่งความรักอันแสนหวาน แต่ความรักอาจแลกข้าวปลาอาหารไม่ได้เสมอไป",
  str_aircraft_tactic_info41001 = "เรดีเซล: วัสดุสีแดงก่ำที่มักใช้ในการทำสี ส่วนใหญ่แล้วผลิตในทะเลทรายเรดีเซล ซึ่งนิยมทาสีสิ่งของส่วนใหญ่ด้วยสีแดง (เนื่องจากไม่มีสีอื่นให้ใช้สอย)",
  str_aircraft_tactic_info41002 = "หนอนทราย: อาหารทั่วไปในทะเลทราย เมื่อทอดแล้วจะมีรสชาติและเนื้อสัมผัสค่อนข้างอร่อย สามารถเก็บไว้กินภายหลังได้สะดวก อย่าประเมินค่าของแมลงพวกนี้ต่ำไป เพราะมันอุดมไปด้วยสารอาหารมีประโยชน์ และถ้าเตรียมอย่างถูกวิธีก็มีรสชาติใกล้เคียงกับไก่เลยทีเดียว!",
  str_aircraft_tactic_info41003 = "กิ้งก่า: อาหารทั่วไปในทะเลทราย โดยทั่วไปจะนำมาตากแห้งก่อนใช้ทำอาหาร เนื้อของมันเคี้ยวมันและมีรสอร่อย ส่วนหนังก็นิยมนำไปฟอกและทำเครื่องหนัง หนังกิ้งก่านั้นมีคุณภาพดีและเป็นที่เสาะหาในหมู่คนนอก",
  str_aircraft_tactic_info41004 = "กระบองเพชร: พืชทะเลทรายหายากที่มักใช้ทำเครื่องดื่มพิเศษ แม้ปริมาณน้ำจะน้อยจนน่าขัน แต่กลิ่นอันหอมหวนของมันกลับสะกดแม้แต่สัตว์กินเนื้อของทะเลทรายได้อย่างชะงัด บางคนกล่าวว่าเครื่องดื่มที่ทำจากกระบองเพชรช่วยเสริมสร้างร่างกายให้แข็งแรงและบำรุงผิวให้สวยงาม",
  str_aircraft_tactic_info41101 = "การสื่อสารในทะเลทรายเรดีเซล (1): ทะเลทรายเรดีเซลไม่มีระบบโทรคมนาคม ข้อมูลส่วนใหญ่เป็นการแลกเปลี่ยนกันเป็นการส่วนตัว ดังนั้น ผู้อยู่อาศัยในทะเลทรายมักจะทราบข้อมูลล้าหลังกว่าภูมิภาคอื่นในโลก ถึงขั้นยังมีบางคนไม่รู้จักลูโมโพลิสด้วยซ้ำ!",
  str_aircraft_tactic_info41102 = "การสื่อสารในทะเลทรายเรดีเซล (2): เมื่อสหพันธรัฐอิลลูมินาได้แนะนำให้รู้จักกับผลิตภัณฑ์ทางเทคโนโลยีพื้นฐาน ชุมชนทะเลทรายขนาดใหญ่ก็เริ่มใช้วิทยุและเครื่องรับส่งสัญญาณมือถือเพื่อพูดคุยติดต่อกัน แม้จะมีการสร้างช่องสื่อสารต่าง ๆ ขึ้นมา แต่ก็มักจะใช้งานซ้ำซ้อนกัน จึงมีการรบกวนสัญญาณบ่อยครั้ง",
  str_aircraft_tactic_info41103 = "อิคลิพไซท์ในทะเลทรายเรดีเซล: อิคลิพไซท์จำนวนมากออกเพ่นพ่านทางเหนือและตะวันตกของทะเลทราย ส่วนทางใต้และตะวันออกมีจำนวนไม่มากและกระจายตัวไม่หนาแน่น แต่ไม่ว่าจะเป็นที่ไหน ผู้อาศัยในทะเลทรายเรดีเซลต้องพึ่งพาประสบการณ์และสัญชาตญาณเอาตัวรอดเพื่อหลีกเลี่ยงการเผชิญหน้ากับอิคลิพไซท์อย่างสุดกำลัง",
  str_aircraft_tactic_info41104 = "การป้องกันอิคลิพไซท์: นิคมทะเลทรายขนาดใหญ่มักสร้างสิ่งปลูกสร้างป้องกันขั้นพื้นฐานไว้ เช่น กำแพงและเชิงเทินเศษเหล็กเพื่อปกป้องตนเองจากการอาละวาดของอิคลิพไซท์ ส่วนชุมชนขนาดเล็กและนักเดินทางที่ไม่มีหลักแหล่งก็ไม่มีทางเลือกนอกจากจะต้องหนีเอาชีวิตรอด",
  str_aircraft_tactic_info41201 = "อัมบราตัน: อัมบราตันเป็นการรวมกลุ่มกันของเมืองต่าง ๆ ที่อยู่ใต้เกาะลอยฟ้าแอชูไรต์ พวกเขาตั้งอยู่ในที่ราบกึ่งกลางแอสตรา มีทำเลเหมาะอย่างยิ่งสำหรับการขนส่งทางบกและใช้เข้าถึงศูนย์กลางการค้าที่มั่งคั่งที่สุดในทวีป นั่นคือลูโมโพลิส",
  str_aircraft_tactic_info41202 = "ต้นกำเนิดของอัมบราตัน: แต่เดิมอัมบราตันถูกกำหนดให้เป็นสลัมของลูโมโพลิสและอยู่ภายใต้การปกครองของเจ้าหน้าที่ปกครองโดยตรง เมื่อเมืองเติบโตและมีประชากรเพิ่มขึ้น การปกครองในอัมบราตันก็เริ่มระส่ำระสาย และในที่สุดก็แยกตัวออกมาเป็นเขตปกครองตนเอง ในปัจจุบัน อัมบราตันปกครองโดยกิลด์พ่อค้าในท้องที่เพียงอย่างเดียว อีกทั้งยังมีแก๊งและองค์กรอาชญากรหลายแห่งคอยแย่งชิงอำนาจกัน",
  str_aircraft_tactic_info41203 = "สถาปัตยกรรมของอัมบราตัน: แม้ส่วนใหญ่บ้านเรือนในอัมบราตันจะทรุดโทรม แออัด และไม่เป็นระเบียบ แต่ก็พบอาคารที่ก่อสร้างและตกแต่งอย่างดีได้ที่ใจกลางเมือง สิ่งปลูกสร้างเหล่านี้หลายแห่งเป็นสำนักงานใหญ่ของกิลด์มากมายในอัมบราตัน และบางส่วนก็เป็นสถานบันเทิงอย่างบาร์และคาสิโน",
  str_aircraft_tactic_info41204 = "การปฏิเสธกำลังทหาร: ก่อนวิกฤตดาร์กโอเวอร์ อัมบราตันไม่เคยเป็นเป้าหมายการโจมตีของอิคลิพไซท์แม้แต่ครั้งเดียว ดังนั้น เมืองจึงแทบไม่ให้ความสำคัญกับการทหารเลย เพราะอย่างไรก็ตาม สังคมที่เน้นการค้าขายเช่นนี้ตัดสินทุกอย่างด้วยทรัพย์สินเป็นหลัก ดังนั้นกองทหารที่แข็งแกร่งจะไปมีความหมายอะไรหากทำเงินไม่ได้?",
  str_aircraft_tactic_info41301 = "โครงสร้างการปกครองของเรดีเซล เวรนช์: เรดีเซล เวรนช์ แบ่งออกเป็นทีมเล็ก ๆ หลายทีม แต่ละทีมทำงานด้วยกฎของตัวเอง และหัวหน้าของแต่ละทีมก็ทำตามและเคารพกฎของหัวหน้าเรดีเซล เวรนช์ ตำแหน่งผู้นำของเรดีเซล เวรนช์ ตัดสินจากพิธีสืบทอดตำแหน่ง โดยหัวหน้าคนต่อไปจะได้รับสืบทอด \"ประแจ\" ซึ่งเป็นสัญลักษณ์แห่งอำนาจในแก๊ง",
  str_aircraft_tactic_info41302 = "ความบันเทิง \"สไตล์เรดีเซล\": สมาชิกเรดีเซล เวรนช์ มีชีวิตเพื่อการปล้นและปล้นเพื่อใช้ชีวิต สำหรับพวกเขาแล้ว ไม่มีอะไรจะตื่นเต้นและสนุกสนานไปกว่าการก่อโจรกรรมอันเร้าใจและเสี่ยงอันตราย ว่ากันว่าในบางครั้ง สมาชิกแก๊งบางคนถึงกับคืนของที่ขโมยมาให้เจ้าของ พร้อมกล่าวว่าเขาสนุกกับการที่ได้ปล้นเฉย ๆ ไม่ได้ต้องการของมีค่าอะไร",
  str_aircraft_tactic_info41303 = "วัฒนธรรมของอัมบราตัน: อัมบราตันมีทัศนคติเสรีและเปิดกว้างกับผู้คนทุกเชื้อชาติและปูมหลัง ทุกคนมีโอกาสคว้าความสำเร็จในอัมบราตัน ตราบใดที่มีสมองและความมุ่งมั่นที่จะไขว่คว้ามันมา ดังนั้นจึงมีธุรกิจมากมายนับไม่ถ้วนเกิดขึ้นทั่วเมือง ให้บริการทุกสิ่งที่ลูกค้าต้องการในราคาที่เหมาะสม",
  str_aircraft_tactic_info41304 = "กฎหมายของอัมบราตัน: อัมบราตันแทบไม่มีกฎที่เขียนขึ้นเป็นลายลักษณ์อักษร เนื่องจากการรักษาความสงบส่วนใหญ่เกิดขึ้นจากอำนาจของแก๊งและองค์กรอาชญากรรมต่าง ๆ โดยสาระสำคัญแล้ว ตราบใดที่ผู้คนไม่ละเมิดหลักการที่กลุ่มอำนาจกำหนดไว้ (หรือถูกจับได้ว่าทำเช่นนั้น) ทุกอย่างก็จะยังถือว่าเป็นการ \"เล่นตามกติกา\" ดังนั้นผู้คนในอัมบราตันจึงนิยมจัดการธุระของตนอย่างลับ ๆ ในเวลากลางคืน",
  str_aircraft_tactic_info50101 = "ต้นกำเนิดของอารีน่าใต้ดิน: อารีน่าใต้ดินใน Umbraton เดิมชื่อ Pit ซึ่งเป็นรูปแบบความบันเทิงยอดนิยมในหมู่ขุนนาง Lumo การต่อสู้อันน่าตื่นเต้นที่เกิดขึ้นที่นั่นยังดึงดูดผู้ชมจำนวนมากจากประชาชนทั่วไป และค่อยๆ พัฒนาเป็นวิธีการยุติข้อพิพาทระหว่างกองกำลังต่างๆ ใน Umbraton",
  str_aircraft_tactic_info50102 = "กฎของอารีน่าใต้ดิน: โดยทั่วไปแล้วการต่อสู้จะจัดขึ้นตั้งแต่เวลา 20.00 น. ถึง 06.00 น. ทีมห้าคนต่อสู้กันเป็นคู่ ไม่มีข้อจำกัดและวิธีการตัดสินผู้ชนะนั้นโหดและตรงไปตรงมา: หากทีมใดทีมหนึ่งยอมแพ้หรือไม่สามารถต่อสู้ได้ทีมนั้นแพ้",
  str_aircraft_tactic_info50103 = "รางวัลในอารีน่าใต้ดิน: ไม่มีแชมป์เปี้ยนผู้ยิ่งใหญ่ในการแข่งขันเหล่านี้ มีเพียงตำแหน่งแชมป์เปี้ยนมิดไนท์ ทีมที่มีคะแนนมากที่สุดและไม่มีการแพ้ในคืนใดคืนหนึ่งจะรักษาเข็มขัดแชมป์ไว้ได้จนถึงคืนถัดไป โดยธรรมชาติแล้ว ทีมใดก็ตามที่สามารถรักษาตำแหน่งแชมป์ได้หลายคืนจะเป็นเป้าหมายของความเคารพ เช่นเดียวกับความอิจฉาริษยา",
  str_aircraft_tactic_info50104 = "การเปลี่ยนแปลงในอารีน่าใต้ดิน: อารีน่าใต้ดินในยุคแรก ๆ วุ่นวายและอันตราย เนื่องจากกองกำลังต่าง ๆ มักใช้เป็นหนทางในการยุติข้อพิพาท เมื่อ Istvan กลายเป็น Shadowlord เขาสร้างกฎสามข้อต่อไปนี้: 1. ห้ามฆ่าฝ่ายตรงข้าม 2. ห้ามส่งทีมใดทีมหนึ่งเกิน 3. หากผู้ใดประสงค์จะโต้แย้งผลการแข่งขัน จะต้องยื่นคัดค้านทันที ไม่ใช่ในภายหลัง",
  str_aircraft_tactic_info50201 = "การปกครองของ Umbraton ของ Lumopolis: หาก Lumopolis เคยบริหาร Umbraton มาก่อน นั่นก็คือการเก็บภาษี เหล่าขุนนางไม่เคยสนใจว่า Umbraton จะกลายเป็นอะไร มีเพียงเงินที่พวกเขาสามารถบีบออกมาได้ ผลที่ตามมาก็คือ นายอำเภอและคนเก็บภาษีที่ได้รับมอบหมายให้ดูแล Umbraton อยู่ร่วมกับพวกอันธพาลและกิลด์ที่นี่ในไม่ช้า และตกเป็นทาสของเงินของ Umbraton",
  str_aircraft_tactic_info50202 = "ความปลอดภัยทางธุรกิจใน Umbraton: กฎข้อเดียวใน Umbraton คือไม่มีกฎใดๆ บางทีคุณอาจเรียกสิ่งนี้ว่าอิสรภาพก็ได้ ดังนั้นเพื่อความปลอดภัยของพวกเขา กิลด์ขนาดใหญ่มักจะจัดตั้งกองกำลังติดอาวุธส่วนตัว กิลด์ขนาดเล็กจะรวบรวมทรัพยากรของพวกเขาในการร่วมทุนเพื่อรับสมัครทหารรับจ้าง และผู้ค้ารายบุคคลมักจะจ่ายค่าคุ้มครองให้กับแก๊งค์หรือกิลด์ใดกิลด์หนึ่ง",
  str_aircraft_tactic_info50203 = "The Gangs of Umbraton: ขุนนางที่ถูกเนรเทศจาก Lumopolis มีแนวโน้มที่จะจัดโครงสร้างชีวิตของพวกเขาใน Umbraton โดยอาศัยครอบครัว ในขณะที่ผู้ละทิ้งสหพันธ์ Illumina ยังคงรักษาโครงสร้างแบบลำดับชั้นที่พวกเขาคุ้นเคย แก๊งท้องถิ่นที่แตกต่างกันในขณะเดียวกันก็ทักทายกันด้วยคำแสลงและคำพูดตามท้องถนน Umbraton ยินดีต้อนรับและรองรับทุกท่าน",
  str_aircraft_tactic_info50204 = "อุตสาหกรรมมืด: ในตรอกซอกซอยต่างๆ ของ Umbraton ผู้ซื้อสามารถหาอะไรก็ได้ที่ต้องการ—อาวุธจาก Illumina Federation ของใช้ในบ้านจากขุนนาง Lumo และแม้แต่ Eclipsites... ไม่ต้องถามว่ามาจากไหน",
  str_aircraft_tactic_info50301 = "อุตสาหกรรมอาวุธใน Umbraton: ปืนไรเฟิล กระสุน และปืนพกของเจ้าหน้าที่จาก Illumina ชุดเกราะและโล่ของทหารจาก Lumopolis และแม้แต่ดาบยาวที่มีตราประจำตระกูลขุนนางสามารถพบได้ใน Umbraton... ตราบใดที่ผู้ซื้อ สามารถจ่ายราคา.",
  str_aircraft_tactic_info50302 = "ธุรกิจด้านกฎหมาย: หากคุณต้องการซื้ออาวุธใน Umbraton ไม่ควรถามคำถามมากเกินไปว่ามาจากไหน นักธุรกิจ Umbraton คนใดก็ตามจะบอกคุณว่าสินค้าของพวกเขาถูกกฎหมาย แต่ข้อความนั้นควรพิจารณาด้วยเกลือเม็ดหนึ่ง",
  str_aircraft_tactic_info50303 = "ขายอาวุธ: ในฐานะที่เป็นศูนย์กระจายสินค้าหลักสำหรับกลุ่มที่ต้องการพลิกสินค้าเพื่อทำกำไร อาวุธใน Umbraton นั้นขายแบบส่วนตัว ผู้ซื้อที่ยินดีจ่ายในราคานี้ยังสามารถออกค่าคอมมิชชั่นลับได้ และใครบางคนใน Umbraton จะสามารถครอบครองสิ่งที่พวกเขากำลังมองหาได้",
  str_aircraft_tactic_info50304 = "Side Gig Economy: เพื่อหลีกเลี่ยงความยุ่งยากที่ไม่จำเป็น ไม่มีกิลด์หรือบุคคลใดอ้างว่าเป็นพ่อค้าอาวุธ อย่างไรก็ตาม ผู้ซื้อสามารถรับอาวุธจากบุคคลหรือกิลด์ใดก็ได้หากพวกเขาสามารถหาสถานที่ที่เหมาะสมเพื่อประกาศข้อเสนอที่สมเหตุสมผลได้ นี่คือความเป็นสองด้านของความเป็นมืออาชีพและงานเสริมใน Umbraton",
  str_aircraft_tactic_info50401 = "ข้อความที่ตัดตอนมาจากประเพณีการแต่งงานของชาวลูโมโปลิส: โดยทั่วไปแล้ว การแต่งงานในลูโมโปลิสนั้นค่อนข้างจะเป็นแบบศักดินา โดยเฉพาะอย่างยิ่งเมื่อเป็นเรื่องของการแต่งงานระหว่างชนชั้น ประการแรก ขุนนางและสามัญชนไม่ได้รับอนุญาตให้แต่งงานระหว่างกัน ประการที่สอง ทั้งสองฝ่ายในการแต่งงานต้องได้รับความยินยอมจากครอบครัวหรือผู้ปกครอง ประการที่สาม พวกเขาฝึกฝนการมีคู่สมรสคนเดียว และคู่สมรสต้องซื่อสัตย์ต่อกัน",
  str_aircraft_tactic_info50402 = "การแต่งงานภายใต้เทพเจ้าแห่งแสงสว่าง: งานแต่งงานจะต้องดำเนินการในวิหารของเทพเจ้าแห่งแสงสว่าง โดยมีนักบวชเป็นพยาน หากไม่ปฏิบัติตามข้อกำหนดเหล่านี้ การแต่งงานจะไม่ได้รับการคุ้มครองและให้พร การนอกใจคู่สมรสเป็นสิ่งต้องห้ามโดยเด็ดขาด และผู้กระทำผิดในอาชญากรรมนี้จะถูกพิจารณาคดี โดยมีบทลงโทษตั้งแต่การกีดกันผู้เยาว์ไปจนถึงความตาย",
  str_aircraft_tactic_info50403 = "ผลที่ตามมาของการละเมิด: ขุนนางที่แต่งงานกับสามัญชนด้วยความรักจะถูกเนรเทศและกลายเป็นสามัญชน ถ้าพวกเขาเป็นพระสงฆ์ พวกเขาจะถูกคว่ำบาตร",
  str_aircraft_tactic_info50404 = "การแต่งงานในพระวิหาร: ผู้ที่ปฏิญาณว่าจะรับใช้พระเจ้าแห่งแสงสว่างตลอดชีวิต เช่น นักบวช จะสูญเสียการเชื่อมต่อกับชีวิตทางโลก ในขณะที่ผู้ที่รับใช้พระวิหาร เช่น อัศวิน จะไม่ได้รับข้อกำหนดที่เข้มงวดโดย พระเจ้าแห่งแสงสว่าง",
  str_aircraft_tactic_info50501 = "ขั้นตอนการเยี่ยมชมลูโมโพลิส: แทบจะเป็นไปไม่ได้เลยที่คนทั่วไปจะเข้าไปในลูโมโปลิสได้ ยกเว้นคนพิเศษบางคน คนธรรมดาสามารถหาทางเข้าไปใน Umbraton ได้หลายวิธี ซึ่งโดยธรรมชาติแล้วมีราคาแพงและต้องใช้ความอดทนมาก เพราะจะต้องทนรอตรวจนานในเขตเปลี่ยนเครื่อง",
  str_aircraft_tactic_info50502 = "เขตเปลี่ยนผ่าน: เดิมทีเป็นสถานีขนส่งระหว่าง Umbraton และ Lumopolis ค่อยๆ กลายเป็นเขตเปลี่ยนผ่านเนื่องจากมีกองคาราวานจำนวนมากอยู่ที่นั่น ในสถานที่นี้ Lumopolis ได้ทำการตรวจกองคาราวานและบุคลากรเบื้องต้นก่อนที่จะเข้าเมือง",
  str_aircraft_tactic_info50503 = "Lumopolis' Vetting: การเข้าสู่ Lumopolis ไม่ใช่เรื่องง่าย เนื่องจากผู้คนต้องผ่านการตรวจสอบตัวตนที่ยาวนานและน่าเบื่อหน่ายก่อนที่จะได้รับอนุญาตให้เข้าได้ แน่นอนว่าหากมีจดหมายแนะนำตัวที่มีตราประจำตระกูลขุนนาง เวลารอก็จะลดลงอย่างมาก",
  str_aircraft_tactic_info50504 = "ที่อยู่อาศัยหนาแน่น: ความประทับใจแรกของผู้คนต่อเขตเปลี่ยนผ่านมักจะเป็นแบบแผนเหมือนกับบ้านอัมบราตัน คือมีบ้านจำนวนมากอยู่รวมกันอย่างหนาแน่นในลักษณะที่ไม่เป็นระเบียบ เนื่องจากเดิมทีบ้านที่นี่สร้างขึ้นเพื่ออำนวยความสะดวกในการเดินทางไปยังสถานีขนส่งเดิมได้อย่างรวดเร็ว ความหนาแน่นสูงยังทำให้สถานที่นี้ป้องกันการคุกคามจากถิ่นทุรกันดารได้ง่ายขึ้น ทำให้ผู้อยู่อาศัยรู้สึกปลอดภัย ",
  str_aircraft_tactic_info50601 = "ผู้คนกำลังรอ: เหตุผลของผู้คนในการเข้าสู่ลูโมโปลิสนั้นแตกต่างกันไป ตั้งแต่การมาเยี่ยมครอบครัวและเพื่อนฝูง ไปจนถึงธุรกิจ การท่องเที่ยว หรือเพียงแค่ได้ชมวิหารอันยิ่งใหญ่ของเทพเจ้าแห่งแสง การรอนั้นยาวนานและน่าเบื่อหน่าย และโรงแรมแถวต่อแถวในเขตเปลี่ยนเครื่องก็รองรับคนเหล่านี้",
  str_aircraft_tactic_info50602 = "เจ้าของโรงแรมในเขตเปลี่ยนผ่าน: เพื่อแสดงให้เห็นว่าพวกเขามีอารยธรรมมากเพียงใด ชาวเมืองลูโมโพลิสตอนล่างบางคนจึงรวบรวมเงินทุนเพื่อก่อตั้งโรงแรมขนาดเล็ก พวกเขาสามารถต้อนรับผู้มาเยือนได้ในขณะเดียวกันก็แสดงพลังของ Lumopolis ให้พวกเขาเห็นด้วย โรงแรมขนาดเล็กที่ได้รับสิทธิพิเศษจากกลุ่มใหญ่ของ Lumopolis จะรับเฉพาะแขกที่ได้รับเชิญจากครอบครัวเท่านั้น โรงแรมอื่นๆ ได้รับทุนจากวัดและเป็นสิทธิพิเศษสำหรับผู้ติดตามของ God of Light โรงแรมขนาดเล็กที่เปิดโดยกิลด์ใหญ่ๆ ใน Umbraton รองรับกองคาราวาน แต่ก็เปิดให้บริการแก่ผู้สัญจรไปมาเช่นกัน ท้ายที่สุดแล้ว ผู้คนใน Umbraton จะไม่มีวันปล่อยโอกาสทำเงินไป",
  str_aircraft_tactic_info50603 = "บริการโรงแรมในเขตเปลี่ยนเครื่อง: นอกจากอาหารและที่พักตามปกติแล้ว โรงแรมขนาดเล็กในเขตเปลี่ยนเครื่องยังให้ข้อมูลต่างๆ แก่ผู้พัก ซึ่งส่วนใหญ่รวมถึงการแนะนำเกี่ยวกับ Lumopolis รวมถึงตระกูลขุนนาง คนดัง ความเชื่อ และอื่นๆ โดยธรรมชาติแล้ว ยังไม่มีปัญหาการขาดแคลนผู้คนที่มีสายสัมพันธ์ที่ดีซึ่งสามารถให้บริการหล่อลื่นความสัมพันธ์สำหรับผู้ที่ไม่สามารถทนต่อกระบวนการตรวจสอบที่ยาวนานได้",
  str_aircraft_tactic_info50604 = "มุมมองและราคาของบ้านในเขตเปลี่ยนผ่าน: เนื่องจากที่อยู่อาศัยหนาแน่นมาก ผู้คนที่อยู่ในเขตเปลี่ยนผ่านมีมุมมองที่จำกัดจากหน้าต่างของพวกเขา ซึ่งหมายความว่าโรงแรมขนาดเล็กที่มีหลายชั้นหรือตั้งอยู่ในทำเลที่ดีและบนพื้นที่สูงนั้นมีราคาแพง ท้ายที่สุดแล้ว มุมมองที่ดีจะทำให้ชีวิตสะดวกสบายขึ้นในขณะที่รอเข้าสู่ลูโมโปลิส ",
  str_aircraft_tactic_info50701 = "สัญลักษณ์ตระกูลขุนนางและตระกูล: ใน Lumopolis ตราประจำตระกูลจะแสดงให้เห็นว่าบุคคลใดเป็นสมาชิกของครอบครัวใดและสถานะของพวกเขาเป็นอย่างไรใน Lumopolis แม้ว่ารูปแบบที่สลับซับซ้อนจะดูเหมือนการเขียนเชิงลึกสำหรับคนนอก แต่ทุกคนใน Lumopolis คุ้นเคยกับรูปแบบเหล่านี้ ท้ายที่สุดแล้วสิ่งเหล่านี้เป็นส่วนสำคัญในชีวิตประจำวันของพวกเขา",
  str_aircraft_tactic_info50702 = "สัญลักษณ์ของวิหาร: ความเชื่อในเทพเจ้าแห่งแสงสว่างนั้นแพร่หลายไปทั่วลูโมโปลิส เมื่อได้รับอนุญาตจากวัด ผู้ศรัทธาสามารถสวมสัญลักษณ์ของเทพเจ้าแห่งแสงสว่างหรือปักลงบนเสื้อผ้าเพื่อแสดงความจงรักภักดีต่อเทพเจ้าแห่งแสงสว่าง",
  str_aircraft_tactic_info50703 = "ชุดที่เป็นทางการของ Umbraton: ทำจากผ้าไหมล้ำค่าจากตะวันออกหรือวัสดุล้ำค่าอื่นๆ จากทวีป เสื้อผ้าของผู้คนที่นี่ดูสวยงาม สวมใส่สบาย และประดับด้วยเครื่องประดับต่างๆ สีทองเข้มและสีม่วงเป็นสองโทนสีโปรดของผู้คนใน Umbraton สีเหล่านี้แสดงถึงทัศนคติอีกอย่างที่พวกเขามีต่อชีวิต นั่นคือการคงไว้ซึ่งความไม่เชื่องเสมอ ",
  str_aircraft_tactic_info50704 = "ชุดลำลองของ Umbraton: รองเท้าหนังและเสื้อโค้ท ผ้าพันคอ และผ้าโพกหัวที่ปิดทั้งหน้า—นี่คือเสื้อผ้าที่ชาว Umbraton มักจะสวมใส่ สิ่งเหล่านี้ช่วยปกปิดใบหน้าและอาวุธต่าง ๆ ที่พวกเขาถือได้ดีขึ้น",
  str_aircraft_tactic_info50801 = "กฎหมายของ Lumopolis: ขุนนางและสามัญชนอยู่ภายใต้กฎหมายที่แตกต่างกัน สถานะและอำนาจที่สอดคล้องกันของครอบครัวให้สิทธิที่แตกต่างกัน เช่นเดียวกับความคุ้มกันบางอย่าง",
  str_aircraft_tactic_info50802 = "การพิจารณาคดีใน Lumopolis: โดยทั่วไปแล้ว Hall of Justice ใน Lumopolis มีหน้าที่ในการตัดสินคดี ในขณะที่สภาผู้สูงอายุจะจัดการคดีที่เกี่ยวข้องกับขุนนาง ในสถานการณ์หลัง ผู้พิพากษาจะได้รับการแต่งตั้งโดยเจ้าเมือง การแต่งตั้งหัวหน้าผู้พิพากษาต้องได้รับความเห็นชอบอย่างเป็นเอกฉันท์จากสภาผู้สูงอายุและวัด ซึ่งมักจะเป็นผลมาจากการถ่วงดุลอำนาจระหว่างหลายฝ่าย",
  str_aircraft_tactic_info50803 = "การลงโทษใน Lumopolis: ไพร่และขุนนางที่ก่ออาชญากรรมร้ายแรงจะต้องรับผิดชอบร่วมกันและมักจะถูกประหารชีวิตด้วยดาบหรือแขวนคอ คนที่กระทำความผิดเล็กน้อยจะถูกจำคุกหรือถูกเนรเทศ",
  str_aircraft_tactic_info50804 = "ตะแลงแกงในลูโมโปลิส: เมื่อมีการประหารชีวิต จะมีการตั้งตะแลงแกงชั่วคราวที่จัตุรัส พวกเขามักจะมีเสาตั้งตรงสำหรับมัดนักโทษ กิโยติน และโครงไม้สำหรับแขวน",
  str_aircraft_tactic_info50901 = "มรดกใน Umbraton: แม้ว่าผู้คนใน Umbraton จะให้ความสำคัญอย่างมากกับความมั่งคั่ง แต่พวกเขาไม่สามารถนำติดตัวไปได้เมื่อพวกเขาถึงบั้นปลายชีวิต ตามธรรมชาติแล้ว ชาว Umbraton ส่วนใหญ่ทิ้งความมั่งคั่งและสถานะของตนไว้กับลูกหลานทางสายเลือด",
  str_aircraft_tactic_info50902 = "ผลกระทบของเจตจำนง: ชาวเมือง Umbraton ที่ใช้ชีวิตอย่างสันโดษหรือด้วยเหตุผลต่างๆ นานา ไม่มีญาติทางสายเลือดมักจะจัดทำพินัยกรรมเมื่อสิ้นสุดชีวิตของพวกเขา คนรู้จักหรือแก๊งที่เชื่อถือได้จะได้รับความไว้วางใจให้จัดการทรัพย์สินและจัดการเพื่อสืบทอดสถานะของพวกเขา",
  str_aircraft_tactic_info50903 = "บทบาทของผู้บังคับบัญชาที่สอง: สำหรับกิลด์ขนาดใหญ่ บางครั้งทั้งทายาทสายเลือดและพินัยกรรมอาจประสบอุบัติเหตุ เช่น การเสียชีวิตอย่างกะทันหันของทายาทหรือการมรณกรรมของผู้หลักที่ยังไม่ได้จัดทำพินัยกรรม ในกรณีดังกล่าวส่วนใหญ่ ผู้บังคับบัญชาคนที่สองจะสืบทอดตำแหน่งของตน โดยปกติแล้วการแต่งตั้งผู้บังคับบัญชาคนที่สองมีแนวโน้มที่จะทำให้เกิดข้อพิพาทต่างๆ",
  str_aircraft_tactic_info50904 = "การปกครองของฝูงชน: การสืบราชสันตติวงศ์หลายครั้งกลายเป็นความขัดแย้งเนื่องจากความมั่งคั่งและสถานะที่เกี่ยวข้อง ซึ่งเป็นสาเหตุของการนองเลือดมากมายในอัมบราตัน มักจบลงด้วยการที่ฝ่ายใดฝ่ายหนึ่งชนะ หรือบ่อยกว่านั้นคือแพ้ทั้งสองฝ่าย โดยไม่มีใครรับช่วงต่อ ณ จุดนี้ บุคคลสำคัญใน Umbraton ปรากฏตัวเพื่อร่วมกันตัดสินใจว่าควรจัดการอย่างไร หลังจากที่ Shadowlord เข้าควบคุมพื้นที่ ผู้คนก็เคารพการตัดสินใจของเขาในเรื่องดังกล่าว",
  str_aircraft_tactic_info51001 = "อุปกรณ์การอ่าน: ใน Umbraton ใครก็ตามที่สามารถจ่ายได้สามารถพิมพ์งานเขียนด้วยเครื่องมิมีโอกราฟได้ ด้วยเหตุนี้ เมืองจึงเจริญรุ่งเรืองด้วยสิ่งตีพิมพ์ทุกประเภท รวมถึงนิตยสาร วารสาร หนังสือพิมพ์ และใบปลิว",
  str_aircraft_tactic_info51002 = "ต้นฉบับ: สามัญชนใน Lumopolis ไม่ได้รับอนุญาตให้เป็นเจ้าของหนังสือ รวมถึงสำเนาที่เขียนด้วยลายมือ เฉพาะคฤหาสน์ของขุนนางและวัดเท่านั้นที่เก็บต้นฉบับจำนวนมาก นี่ไม่ใช่เพียงเพราะพวกเขาได้รับอนุญาตเท่านั้น แต่ส่วนใหญ่เป็นเพราะพวกเขาสามารถที่จะเก็บผู้ลอกเลียนแบบจำนวนมากได้",
  str_aircraft_tactic_info51003 = "ม้วนกระดาษ: นักท่องเที่ยวไม่ควรแปลกใจที่เห็นชาวเหนือใช้เชือกผูกปม แผ่นไม้จารึกไว้ หรือแม้แต่แผ่นหินเล็กๆ ที่มีตัวอักษรสลักไว้ นี่คือหนังสือของพวกเขา ใน Northland ที่ซึ่งการบอกปากต่อปากเป็นวิธีการหลักในการส่งต่อข้อความ สื่อการอ่านเป็นสิ่งที่หาได้ยาก และมีเพียงเหตุการณ์สำคัญเท่านั้นที่จะถูกบันทึกไว้ในม้วนหนังสือที่ทำจากกระดาษสำหรับเก็บรักษา",
  str_aircraft_tactic_info51004 = "หนังสือส่วนตัว: หากคุณเห็นหนังสือเล่มเล็กหรือม้วนหนังสือที่เขียนด้วยลายมือซึ่งมีข้อความที่ไม่สามารถจดจำได้ เป็นไปได้มากว่าสิ่งเหล่านี้เป็นผลงานของบางองค์กรที่ต้องการเก็บการติดต่อของพวกเขาไว้เป็นความลับ ดังนั้นจึงใช้ข้อความที่เข้ารหัสสำหรับเอกสารของพวกเขา",
  str_aircraft_tactic_info51101 = "หนังสือพิมพ์ใน Umbraton: นักข่าวหนังสือพิมพ์มักจะยุ่งอยู่เสมอ ท้ายที่สุดแล้ว หนังสือพิมพ์ต้องการเนื้อหาที่สดใหม่ เพื่อความรวดเร็ว สำนักข่าวขนาดใหญ่ส่วนใหญ่มีเครื่องพิมพ์เกรดต่ำสุดที่สามารถพิมพ์หนังสือพิมพ์ได้หลายพันฉบับในทันทีที่มีการเขียนเนื้อหาและเรียงพิมพ์ หนังสือพิมพ์ขนาดเล็กมักจ้างคนขับรถเฉพาะทางเพื่อส่งต้นฉบับไปยังโรงพิมพ์อย่างรวดเร็ว คนอื่น ๆ ที่มีเพียงไม่กี่คนทำงานให้พวกเขาใช้เครื่องพิมพ์แบบแมนนวลเพื่อเลียนแบบ โดยธรรมชาติแล้ว หนังสือพิมพ์ดังกล่าวจะออกในปริมาณที่น้อยกว่า และคุณภาพก็ค่อนข้างแย่ด้วย",
  str_aircraft_tactic_info51102 = "นิตยสาร Umbraton: เนื่องจากมีเพียงโรงพิมพ์เท่านั้นที่มีวัสดุเข้าเล่มและทำปกโดยเฉพาะ หากคุณต้องการพิมพ์นิตยสาร คุณต้องส่งไปยังโรงพิมพ์ที่เชี่ยวชาญ อย่างไรก็ตาม ผู้จัดพิมพ์นิตยสารบางรายยังใช้เครื่องพิมพ์แบบแมนนวลและช่างฝีมือที่ไม่ใช่มืออาชีพในการพิมพ์และเข้าเล่มนิตยสาร ส่งผลให้นิตยสารมีคุณภาพต่ำลง ดังนั้นพวกเขาจึงต้องพึ่งพาพาดหัวข่าวที่ค้นหาความแปลกใหม่และการเผยแพร่อย่างรวดเร็วเพื่อรักษาตำแหน่งในตลาด ณ จุดนี้ นิตยสารเหล่านี้ไม่ต่างจากหนังสือพิมพ์จริงๆ",
  str_aircraft_tactic_info51103 = "นวนิยายของ Umbraton: เสรีภาพในการพูดเป็นจริยธรรมที่สำคัญที่สุดใน Umbraton ทุกคนสามารถเผยแพร่ผลงานของตนได้ตราบเท่าที่พวกเขาสามารถจ่ายค่าใช้จ่ายในการพิมพ์และจัดจำหน่ายได้ หากเนื้อหารุนแรงเกินไป โรงพิมพ์และผู้จำหน่ายหนังสือจะยังคงลังเลว่าควรเอาเงินไปหรือไปใช้ชีวิตต่อ",
  str_aircraft_tactic_info51104 = "หนังสือความรู้ใน Umbraton: มีเพียงไม่กี่คนที่แสดงความสนใจในหนังสือความรู้เนื่องจากลัทธิปฏิบัตินิยมหรือแม้แต่ฆราวาสนิยมที่ครอบงำใน Umbraton ทุกคนยุ่งกับการหาเงิน คนที่กล้าตีพิมพ์หนังสือดังกล่าวใน Umbraton นั้นมีทั้งนักวิชาการที่ร่ำรวยหรือได้รับการสนับสนุนจากองค์กรบางแห่งอย่างลับๆ",
  str_aircraft_tactic_info51201 = "ข่าวใน Lumopolis: เนื่องจากมีชนชั้นขุนนางและสามัญชนที่แตกต่างกัน จึงไม่มีการเผยแพร่ข่าวสาธารณะใน Lumopolis ขุนนางสนใจเฉพาะสิ่งที่เกิดขึ้นในแวดวงระดับสูงซึ่งข่าวที่คนทั่วไปไม่เคยได้ยินจะถูกแพร่กระจายด้วยปากต่อปาก ส่วนสามัญชนก็เอาแต่กังวลว่าการกระทำใด ๆ ของขุนนางหรือวัดที่กระทบกระเทือนต่อชีวิตของตน พวกเขามักจะได้รับแจ้งในเรื่องดังกล่าวจากประกาศของเจ้าหน้าที่ฝ่ายปกครองต่างๆ ใน Lumopolis บางครั้ง Lumopolis ได้รับข้อมูลเกี่ยวกับโลกภายนอกเมื่อมีคนนำหนังสือพิมพ์มาจาก Umbraton",
  str_aircraft_tactic_info51202 = "คอลเลกชันหนังสือของ Lumopolis: วิหารของ Lumopolis มีหนังสือสะสมมากที่สุด บุคลากรเฉพาะด้านถอดความหนังสือต่างๆ จัดหมวดหมู่ และเก็บบันทึก หนังสือถูกเก็บไว้ในห้องสมุดซึ่งเปิดให้เฉพาะเจ้าหน้าที่ของวัดเท่านั้น ขุนนางยังเก็บห้องสมุดเล็กๆ ไว้ในบ้าน และจัดให้มีชมรมหนังสือและร้านทำผมที่ค่อนข้างพิเศษ",
  str_aircraft_tactic_info51203 = "หนังสือของวิหาร: หนังสือที่ครอบคลุมบทความต่างๆ เกี่ยวกับศาสนาของเทพเจ้าแห่งแสงสว่าง ปาฏิหาริย์ที่มีชื่อเสียง และประสบการณ์ของผู้ศรัทธาเป็นของสะสมส่วนใหญ่ในวิหารลูโมโปลิส โดยธรรมชาติแล้ว พระที่มีแนวคิดเสรีนิยมบางรูปจะใช้ความเข้าใจเกี่ยวกับเทพเจ้าแห่งแสงสว่างเพื่อเขียนเรื่องราวทางโลกที่น่าสนใจเพื่อให้ผู้คนจำนวนมากขึ้นอ่านและเข้าใจเทพเจ้าแห่งแสงสว่าง",
  str_aircraft_tactic_info51204 = "พ่อค้าหนังสือใน Lumopolis: ในบางช่วงเวลา สามัญชนจาก Lumopolis ปรากฏตัวใน Umbraton โดยถือกองเงินและกองต้นฉบับที่จะพิมพ์และเผยแพร่ ผู้ค้าหนังสือเหล่านี้ได้รับเงินอุดหนุนจากขุนนางหรือวัด ค่อนข้างผิดปกติใน Umbraton พวกเขาไม่แสวงหากำไรแต่สนใจคุณภาพการพิมพ์และการหมุนเวียนของหนังสือมากกว่า ท้ายที่สุดแล้ว ในสายตาของสามัญชนเหล่านี้ การทำภารกิจที่ได้รับจากผู้นำให้สำเร็จนั้นสำคัญกว่าการหาเงิน",
  str_aircraft_tactic_info51301 = "Secret Court of Lumopolis: ในสวน Lumopolis มีสถานที่สำหรับเก็บไฟล์และเอกสารสำคัญไว้เป็นความลับ กล่าวกันว่ามีเพียงลอร์ดแห่งลูโมโพลิส สมาชิกสำคัญของสภาผู้อาวุโส และตัวแทนของตระกูลขุนนางสำคัญเท่านั้นที่สามารถเข้าถึงมันได้",
  str_aircraft_tactic_info51302 = "อัญมณีแห่ง Lumopolis: Daybreak Crystal เป็นแร่หายากที่กล่าวกันว่าไม่พบในเส้นเลือด แต่พบได้ในที่ที่ดูเหมือนสุ่ม ซึ่งทำให้ยากต่อการค้นหาและขุด แม้แต่แร่ดิบก็ยังเปล่งสีที่ต่างกันภายใต้แสงที่ต่างกันและจากมุมที่ต่างกัน ในขณะที่หินขัดเงาก็ปล่อยสีที่เป็นภาพลานตาอย่างแท้จริง แม้แต่ขุนนางลูโม่ที่เคยเห็นสมบัติแปลกใหม่มานับไม่ถ้วน ก็ไม่สามารถต้านทานเสน่ห์ของมันได้",
  str_aircraft_tactic_info51303 = "ภาพวาดจำลองของ Umbraton: เมื่อสินค้าฟุ่มเฟือยของ Lumopolis ได้รับการแนะนำให้รู้จักกับ Umbraton พวกเขาไม่เพียงนำความมั่งคั่งมาสู่คนในท้องถิ่นเท่านั้น แต่ยังเป็นแรงบันดาลใจให้พวกเขาชื่นชมศิลปะอีกด้วย เมื่อผู้คนร่ำรวยพอที่จะไม่ต้องกังวลเรื่องการทำมาหากิน พวกเขาก็เริ่มติดตามศิลปะแห่งลูโมโปลิส และด้วยเหตุนี้อุตสาหกรรมการจำลองแบบจึงถือกำเนิดขึ้น ภาพวาดสีน้ำมันที่มีชื่อเสียงทุกชนิดสามารถพบได้ใน Umbraton จัดแสดงทุกที่ รวมถึงกิลด์ คาเฟ่ และบาร์ มีข่าวลือว่าพิธีเริ่มต้นของแก๊งบางกลุ่มเกี่ยวข้องกับการเผาภาพวาด",
  str_aircraft_tactic_info51304 = "Umbraton Wariness: เจ้าของธุรกิจขนาดเล็กใน Umbraton มีความอ่อนไหวต่อเงินและอาณาเขตมาก มักจะระมัดระวังในขอบเขตการดำเนินงานและหลีกเลี่ยงการข้ามขอบเขตที่ไม่ได้พูด ตัวอย่างเช่น คนขายขนมขบเคี้ยวใน East End จะไม่ทำธุรกิจในฝั่งตะวันตกแม้ว่าจะมีความต้องการที่จะตอบสนองความต้องการและต้องทำเงินมากขึ้นก็ตาม เพราะเป็นไปได้มากว่าคนขายขนมขบเคี้ยวจะให้บริการในพื้นที่โดยได้รับการคุ้มครองแบบชำระเงินอยู่แล้วและจะ มีสิทธิ์ขับไล่คู่แข่งได้ทุกอย่าง"
